/* ---------- Helpers ---------- */
const lvl = (s) => player.skills[s]?.level || 1;
const clamp = (v, a, b) => Math.max(a, Math.min(b, v));
function cheb(ax, ay, bx, by) { return Math.max(Math.abs(ax - bx), Math.abs(ay - by)); }
function npcById(id) { return npcs.find(n => n.id === id || n.sid === id); }
function objById(id) { return worldObjects.find(o => o.id === id) || sceneryTrees.get(id); }
function campaignStepIndex(id) { return CAMPAIGN.findIndex(s => s.id === id); }
function currentStep() { return (campaignState().status === 'done') ? null : CAMPAIGN[campaignState().step] || null; }

function isObjHidden(o) {
  if (o.type === 'starshard') return (campaignState().status === 'done') || campaignStepIndex(o.shardStep) < campaignState().step;
  return false;
}
function rebuildObjectBlock() {
  objectBlock.clear();
  for (const o of worldObjects) if (!isObjHidden(o)) objectBlock.add(tKey(o.x, o.y));
  walkGridDirty = true;
}
/* Walkability as one byte per sector, rebuilt when objects or scenery change: keeps long-distance pathfinding fast */
const walkGrid = new Uint8Array(WORLD_COLS * WORLD_ROWS);
let walkGridDirty = true;
function ensureWalkGrid() {
  if (!walkGridDirty) return;
  for (let y = 0, k = 0; y < WORLD_ROWS; y++) { const row = map[y]; for (let x = 0; x < WORLD_COLS; x++, k++) walkGrid[k] = (BLOCK_TILES.has(row[x]) || objectBlock.has(k) || decorBlocked.has(k)) ? 0 : 1; }
  walkGridDirty = false;
}
function isTileWalkable(x, y) {
  if (x < 0 || y < 0 || x >= WORLD_COLS || y >= WORLD_ROWS) return false;
  if (BLOCK_TILES.has(map[y][x])) return false;
  const k = tKey(x, y);
  return !objectBlock.has(k) && !decorBlocked.has(k);
}
function hasLOS(x0, y0, x1, y1) {
  let dx = Math.abs(x1 - x0), dy = Math.abs(y1 - y0), sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, err = dx - dy;
  let x = x0, y = y0;
  while (!(x === x1 && y === y1)) {
    const e2 = 2 * err;
    if (e2 > -dy) { err -= dy; x += sx; }
    if (e2 < dx) { err += dx; y += sy; }
    if (x === x1 && y === y1) break;
    const lt = map[y]?.[x]; if (lt === 8 || lt === 21) return false;
  }
  return true;
}

const PF_N = WORLD_COLS * WORLD_ROWS;
const pfPrev = new Int32Array(PF_N), pfQueue = new Int32Array(PF_N), pfSeen = new Uint32Array(PF_N);
let pfStamp = 0;
function findPath(sx, sy, gx, gy, range = 0, opts = {}) {
  const maxNodes = opts.maxNodes || 60000;
  const goalOk = (x, y) => range > 0
    ? (cheb(x, y, gx, gy) <= range && !(x === gx && y === gy) && (!opts.los || hasLOS(x, y, gx, gy)))
    : (x === gx && y === gy);
  if (goalOk(sx, sy)) return [];
  if (range === 0 && !isTileWalkable(gx, gy)) return findPath(sx, sy, gx, gy, 1, opts);
  ensureWalkGrid();
  const W = WORLD_COLS, H = WORLD_ROWS;
  if (++pfStamp >= 0xffffffff) { pfSeen.fill(0); pfStamp = 1; }
  const stamp = pfStamp, start = sy * W + sx;
  pfSeen[start] = stamp; pfPrev[start] = start;
  let qh = 0, qt = 0; pfQueue[qt++] = start;
  const occ = opts.occupied || null;
  let found = -1, visited = 0;
  while (qh < qt && visited < maxNodes) {
    const cur = pfQueue[qh++]; visited++;
    const cx = cur % W, cy = (cur / W) | 0;
    for (let d = 0; d < 8; d++) {
      const dx = DIRS8[d][0], dy = DIRS8[d][1], nx = cx + dx, ny = cy + dy;
      if (nx < 0 || ny < 0 || nx >= W || ny >= H) continue;
      const ni = ny * W + nx;
      if (pfSeen[ni] === stamp || !walkGrid[ni]) continue;
      if (dx && dy && (!walkGrid[cy * W + nx] || !walkGrid[ny * W + cx])) continue;
      if (occ && occ.has(ni)) continue;
      pfSeen[ni] = stamp; pfPrev[ni] = cur;
      if (goalOk(nx, ny)) { found = ni; break; }
      pfQueue[qt++] = ni;
    }
    if (found !== -1) break;
  }
  if (found === -1) return [];
  const path = [];
  let c = found;
  while (c !== start) { path.push({ x: c % W, y: (c / W) | 0 }); c = pfPrev[c]; }
  return path.reverse();
}

/* Route the player from where they really are. Once the character is past halfway into the next sector, the route
   starts from that sector, so re-clicking or chasing a moving target never yanks them back. Player routes also get a
   bigger search budget than enemies, and a plain walk to somewhere unreachable goes to the nearest spot you can reach. */
function routeTo(gx, gy, range = 0, opts = {}) {
  opts = Object.assign({ maxNodes: 200000 }, opts);
  const path = routeFrom(gx, gy, range, opts);
  if (path.length || range > 0 || !opts.nearest || (player.x === gx && player.y === gy)) return path;
  // unreachable spot (water, a wall, a sealed area): walk to the closest reachable sector instead
  const cands = [];
  for (let r = 1; r <= 8; r++) for (let dy = -r; dy <= r; dy++) for (let dx = -r; dx <= r; dx++) {
    if (Math.max(Math.abs(dx), Math.abs(dy)) !== r || !isTileWalkable(gx + dx, gy + dy)) continue;
    cands.push([gx + dx, gy + dy, Math.hypot(dx, dy)]);
  }
  cands.sort((a, b) => a[2] - b[2]);
  for (const [cx, cy] of cands.slice(0, 10)) { const p2 = routeFrom(cx, cy, 0, opts); if (p2.length || (cx === player.x && cy === player.y)) return p2; }
  return [];
}
function routeFrom(gx, gy, range, opts) {
  const next = player.path[0];
  if (next && (next.x !== player.x || next.y !== player.y) && Math.hypot(next.x - player.visX, next.y - player.visY) < 0.5) {
    const atGoal = range > 0
      ? cheb(next.x, next.y, gx, gy) <= range && !(next.x === gx && next.y === gy) && (!opts.los || hasLOS(next.x, next.y, gx, gy))
      : next.x === gx && next.y === gy;
    if (atGoal) return [next];
    const rest = findPath(next.x, next.y, gx, gy, range, opts);
    if (rest.length) return [next, ...rest];
  }
  return findPath(player.x, player.y, gx, gy, range, opts);
}

/* ---------- Inventory ---------- */
function addItem(key, silent = false) {
  if (!ITEMS[key]) return false;
  const ammo = ITEMS[key].type === 'ammo' ? ITEMS[key] : null;
  if (ammo) { if (ammo.ammo === 'cells') player.cells += ammo.amount; else player.slugs += ammo.amount; markDirty('bars'); markDirty('equip'); return true; }
  if (player.inventory.length >= MAX_INV_SLOTS) {
    if (!silent) addChatMessage(`Your pack is full (${MAX_INV_SLOTS}/${MAX_INV_SLOTS}).`, 'warn');
    return false;
  }
  player.inventory.push(key);
  markDirty('inv');
  return true;
}
function countItem(key) { return player.inventory.filter(k => k === key).length; }
function removeItems(key, n) {
  let removed = 0;
  for (let i = player.inventory.length - 1; i >= 0 && removed < n; i--) if (player.inventory[i] === key) { player.inventory.splice(i, 1); removed++; }
  markDirty('inv');
  return removed;
}
function dropGround(key, x, y, rare = false) {
  groundItems.push({ id: groundItemId++, itemKey: key, x, y, respawnSpot: false, rare, ttl: 400 });
}

/* ---------- Skills ---------- */
function levelFor(skill, xp) {
  let l = 1;
  while (l < 99 && XP_TABLE[l + 1] <= xp) l++;
  return skill === 'Vitality' ? Math.max(10, l) : l;
}
function typeMult(npc, type) {
  const a = ARMOUR_MULT[npc.armour || ARMOUR_BY_MODEL[npc.model] || 'organic'];
  return (a && a[type]) || 1;
}
function abilityDef(id) { return ABILITIES.find(a => a.id === id); }
function abilityList() { return ABILITIES; }
/* Your calling is whichever class lead skill you have trained most */
function callingOf() {
  let best = null, bx = 0;
  for (const [k, c] of Object.entries(CLASSES)) { const xp = player.skills[c.lead]?.xp || 0; if (xp > bx) { bx = xp; best = k; } }
  return best || 'Recruit';
}
const hasSpec = (name) => Object.values(player.specs || {}).includes(name);
function learnSpec(name) {
  const sp = SPECS[name]; if (!sp) return false;
  const lead = CLASSES[sp.cls].lead;
  if (lvl(lead) < SPEC_LEVEL || player.specs[sp.cls]) return false;
  player.specs[sp.cls] = name;
  if (name === 'Dronewright') { droneIndex = 0; updateDroneAppearance(); addChatMessage('Your first combat drone powers up beside you. Change its type in Settings.', 'accent'); }
  playSound('levelup'); showToast(`${name} learned`, `${sp.cls} specialisation`, 'level');
  addChatMessage(`You are now a ${name}: ${sp.desc}`, 'good');
  markDirty('equip'); markDirty('skills');
  return true;
}
function gainXp(skill, amount) {
  const s = player.skills[skill];
  if (!s || amount <= 0) return;
  amount = Math.round(amount * XP_RATE);
  s.xp = Math.min(200000000, s.xp + amount);
  const last = xpDrops[xpDrops.length - 1];
  if (last && last.skill === skill && last.age < 0.25) last.amount += amount;
  else xpDrops.push({ skill, amount, age: 0 });
  const nl = levelFor(skill, s.xp);
  if (nl > s.level) {
    s.level = nl;
    playSound('levelup');
    if (skill === 'Vitality') { player.maxHp = nl; player.hp = player.maxHp; }
    addChatMessage(`${skill} reached level ${nl}.`, 'good');
    showToast(`${skill} ${nl}`, nl === 99 ? 'Mastered' : 'Level up', 'level');
    burst(player.visX, tileTop(player.x, player.y) + 1, player.visY, 0xf5c56b, 24, { speed: 2, up: 3, life: 1, grav: -2 });
  }
  markDirty('skills'); markDirty('bars');
}
function getCombatLevel() {
  const base = 0.25 * (lvl('Aegis') + lvl('Vitality'));
  const melee = 0.325 * (lvl('Vanguard') + lvl('Kinetic'));
  const ranged = 0.325 * Math.floor(lvl('Marksman') * 1.5);
  const magic = 0.325 * Math.floor(lvl('Arcanistry') * 1.5);
  return Math.max(3, Math.floor(base + Math.max(melee, ranged, magic)));
}
function getArmourDef() {
  let def = 0;
  for (const s of EQUIP_SLOTS) { const k = player.equipment[s]; if (k) def += ITEMS[k]?.def || 0; }
  if (player.doctrine === 'Defensive') def += 3;
  if (hasSpec('Juggernaut')) def += 6;
  return def;
}
function doctrineSkill() { return player.doctrine === 'Aggressive' ? 'Kinetic' : (player.doctrine === 'Defensive' ? 'Aegis' : 'Vanguard'); }

function weaponStats(slot) {
  const k = player.equipment[slot];
  const it = k ? ITEMS[k] : null;
  const headAtk = ITEMS[player.equipment.head]?.atk || 0;
  const atk = (it?.atk || 0) + headAtk, str = it?.str || 0;
  let maxHit;
  if (slot === 'sidearm') maxHit = 2 + Math.floor((lvl(it?.skill || 'Marksman') + Math.floor(str / 2)) / 2);
  else maxHit = 2 + Math.floor((lvl('Kinetic') + (player.doctrine === 'Aggressive' ? 2 : 0) + player.tempStr + Math.floor(str / 2)) / 2);
  if (activeDrone() === 'SENTINEL') maxHit += 1;
  return { it, atk, str, maxHit };
}
function hasAmmoFor(it) {
  if (!it || !it.ammo) return true;
  return (it.ammo === 'cells' ? player.cells : player.slugs) >= (it.ammoCost || 1);
}

/* ---------- Targeting ---------- */
function setTarget(npc) {
  if (!npc || npc.dead) return;
  player.task = null;
  player.target = npc.id;
  player.chaseKey = -1;
  updateTargetFrame();
}
function clearTarget() { player.target = null; updateTargetFrame(); }

function stopPlayer() {
  if (player.path.length) {
    const n = player.path[0];
    if (Math.hypot(n.x - player.visX, n.y - player.visY) < 0.5) { player.x = n.x; player.y = n.y; onPlayerTileChanged(); }
  }
  player.path = [];
}

function weaponPlan(npc, warn = false) {
  const prim = player.equipment.primary, side = player.equipment.sidearm;
  const sideIt = side ? ITEMS[side] : null;
  const sideOk = sideIt && hasAmmoFor(sideIt);
  const d = cheb(player.x, player.y, npc.x, npc.y);
  const melee = { slot: 'primary', key: prim, it: prim ? ITEMS[prim] : null, range: 1, ranged: false };
  const ranged = sideOk ? { slot: 'sidearm', key: side, it: sideIt, range: sideIt.range + (hasSpec('Sharpshooter') && !sideIt.skill ? 2 : 0), ranged: true } : null;
  if (warn && sideIt && !sideOk && performance.now() - lastAmmoWarn > 6000 && player.weaponMode !== 'MELEE') {
    lastAmmoWarn = performance.now();
    addChatMessage(`${side} is out of ${sideIt.ammo === 'cells' ? 'Aether Cells' : 'Rail Slugs'}. Switching to melee.`, 'warn');
    const what = sideIt.ammo === 'cells' ? 'Aether Cells' : 'Rail Slugs';
    showToast(`Out of ${what}`, `${side} can't fire, so you're using your melee weapon. Buy ${what} from a quartermaster${sideIt.ammo === 'cells' ? ' or condense crystals at the Mistwood Monolith' : ''}.`, 'warn');
    addOverheadBark(player, 'Out of ammo!', '#f87171');
  }
  let plan;
  if (player.weaponMode === 'MELEE' || !ranged) plan = melee;
  else if (player.weaponMode === 'RANGED') plan = ranged;
  else plan = (d <= 1 && prim) ? melee : ranged;
  const los = plan.ranged ? hasLOS(player.x, player.y, npc.x, npc.y) : true;
  plan.d = d;
  plan.inRange = d >= 1 && d <= plan.range && los;
  return plan;
}

function muzzlePos(out) {
  const f = player.facing, top = tileTop(player.x, player.y);
  out.set(player.visX + Math.sin(f) * 0.45 + Math.cos(f) * 0.27, top + 1.05, player.visY + Math.cos(f) * 0.45 - Math.sin(f) * 0.27);
  return out;
}

function playerCombatTick() {
  if (player.attackCd > 0) player.attackCd--;
  if (player.target === null || playerDead) return;
  const npc = npcById(player.target);
  if (!npc || npc.dead) { clearTarget(); return; }
  const plan = weaponPlan(npc, true);
  if (plan.inRange) {
    if (player.path.length) stopPlayer();
    player.facing = Math.atan2(npc.x - player.x, npc.y - player.y);
    if (plan.ranged) player.aimUntil = performance.now() + 1400;
    if (player.attackCd <= 0) performAttack(plan, npc);
  } else {
    const key = tKey(npc.x, npc.y);
    if (!player.path.length || player.chaseKey !== key) {
      player.chaseKey = key;
      player.path = routeTo(npc.x, npc.y, plan.range, { los: plan.ranged });
      if (!player.path.length && plan.d > plan.range) {
        player.path = routeTo(npc.x, npc.y, 1);
        if (!player.path.length) { addChatMessage(`You cannot reach the ${npc.name}.`, 'warn'); clearTarget(); }
      }
    }
  }
}

function performAttack(plan, npc) {
  const st = weaponStats(plan.slot);
  const it = st.it;
  player.attackCd = it ? Math.max(2, it.speed - (plan.ranged && !it.skill && hasSpec('Gunslinger') ? 1 : 0)) : 4;
  player.lastCombatTick = tickCount;
  setVisualWeapon(plan.slot);
  if (plan.ranged && it.ammo) {
    if (it.ammo === 'cells') player.cells -= it.ammoCost || 1; else player.slugs -= it.ammoCost || 1;
    markDirty('bars');
  }
  const accLvl = plan.ranged ? lvl(it?.skill || 'Marksman') : lvl('Vanguard');
  let hitChance = clamp(0.6 + (accLvl + st.atk * 0.6 - npc.level) * 0.028, 0.22, 0.95);
  if (plan.ranged && plan.d <= 1 && !it?.skill && !hasSpec('Breacher')) hitChance *= 0.65; // Gunners struggle with an enemy in their face
  if (!plan.ranged && hasSpec('Duellist')) hitChance = Math.min(0.97, hitChance + 0.1);
  let maxHit = st.maxHit;
  let empowered = false;
  if (player.overdriveArmed && player.energy >= 50) {
    player.energy -= 50; player.overdriveArmed = false; empowered = true;
    hitChance = 0.98; maxHit = Math.floor(maxHit * 1.6) + 2;
    addChatMessage('Overdrive strike!', 'accent');
    markDirty('abilities');
  }
  const hit = Math.random() < hitChance;
  let dmg = hit ? 1 + Math.floor(Math.random() * maxHit) : 0;
  let crit = false;
  if (hit && Math.random() < 0.08 + (empowered ? 0.25 : 0)) { dmg = Math.ceil(dmg * 1.5); crit = true; }
  let mult = typeMult(npc, it?.dmgType || 'kinetic');
  if (plan.ranged && !it?.skill && hasSpec('Breacher') && plan.d <= 2) mult *= 1.2;
  if (!plan.ranged && hasSpec('Shadowstep') && performance.now() < (player.shadowUntil || 0)) { mult *= 1.5; player.shadowUntil = 0; }
  if (hit) dmg = Math.max(1, Math.round(dmg * mult));
  const opts = { crit, weak: mult > 1, xpSkill: plan.ranged ? (it?.skill || 'Marksman') : doctrineSkill(), splash: it?.splash || 0, empowered, stun: hit && it?.stun && Math.random() < it.stun ? 2 : 0 };
  const apply = () => damageNpc(npc, dmg, opts);
  const tgt = new THREE.Vector3();
  if (plan.ranged) {
    animatePlayer('shoot', 0.32);
    const from = muzzlePos(new THREE.Vector3());
    const glow = it.glow || '#67e8f9';
    if (it.bolt === 'rail') {
      entityAimPos(npc, tgt);
      spawnBeam(from, tgt, glow, 0.05, 0.25);
      flash(from.x, from.y, from.z, glow, 2.5);
      impactFx(tgt.x, tgt.y, tgt.z, glow, 'bolt');
      playSound('rail');
      apply();
    } else {
      const kind = it.bolt === 'plasma' ? 'plasma' : (it.bolt === 'ion' ? 'ion' : 'bolt');
      spawnProjectile({ from, target: npc, kind, color: glow, onHit: apply });
      flash(from.x, from.y, from.z, glow, 1.6);
      playSound(kind === 'plasma' ? 'plasma' : (kind === 'ion' ? 'ion' : 'pistol'));
    }
  } else {
    animatePlayer('melee', 0.45);
    playSound('melee');
    setTimeout(() => {
      apply();
      if (it) { entityAimPos(npc, tgt); burst(tgt.x, tgt.y, tgt.z, it.glow || '#ffffff', 10, { speed: 2.6, up: 1, life: 0.35, size: 0.22 }); }
    }, 190);
  }
  if (empowered) { const p = muzzlePos(new THREE.Vector3()); burst(p.x, p.y, p.z, 0x67e8f9, 20, { speed: 3, up: 2, life: 0.6 }); }
  if (activeDrone() !== 'OFF' && Math.random() < 0.5) droneAssist(npc);
  npc.inCombat = true; npc.returning = false; npc.lastHitTick = tickCount;
  if (npc.neutral) npc.provoked = true;
}

function droneAssist(npc) {
  const cols = { WISP: '#22d3ee', SENTINEL: '#f59e0b', PHOENIX: '#f43f5e' };
  const c = cols[activeDrone()] || '#22d3ee';
  const from = droneMesh.position.clone();
  spawnProjectile({ from, target: npc, kind: 'drone', color: c, onHit: () => {
    if (activeDrone() === 'PHOENIX') { if (!npc.dead) npc.burnTicks = Math.max(npc.burnTicks, 4); }
    else damageNpc(npc, Math.random() < 0.6 ? 1 : 0, { xpSkill: 'Arcanistry', small: true });
  } });
}

function damageNpc(npc, dmg, o = {}) {
  if (npc.dead) return;
  const dealt = Math.min(dmg, npc.hp);
  if (!o.byNpc) { npc.playerDmg = (npc.playerDmg || 0) + dealt; if (o.xpSkill) npc.lastHitSkill = o.xpSkill; }
  npc.hp = Math.max(0, npc.hp - dmg);
  npc.hitT = performance.now();
  const top = tileTop(npc.x, npc.y) + (NPC_AIM_H[npc.model] || 0.9) + 0.6;
  addSplat(npc.visX ?? npc.x, top, npc.visY ?? npc.y, dmg > 0 ? String(dmg) : (o.small ? '' : 'MISS'), o.crit ? 'crit' : (dmg > 0 ? (o.dot ? 'burn' : 'hit') : 'miss'));
  if (dmg > 0) {
    const fxc = { construct: 0x34d399, leviathan: 0xfb923c, archon: 0xf97316, weaver: 0xc084fc, zealot: 0x818cf8 }[npc.model] || 0xef4444;
    burst(npc.visX ?? npc.x, top - 0.6, npc.visY ?? npc.y, fxc, o.crit ? 16 : 7, { speed: 2, up: 1.6, life: 0.45, size: 0.2 });
    if (!o.small && !o.byNpc && dealt > 0) { gainXp('Vitality', dealt * 2); if (o.xpSkill) gainXp(o.xpSkill, dealt * 5); }
    playSound('hit');
  }
  if (o.stun) npc.stunTicks = Math.max(npc.stunTicks, o.stun);
  if (o.burn) npc.burnTicks = Math.max(npc.burnTicks, o.burn);
  npc.inCombat = true; npc.returning = false;
  if (!o.byNpc && !o.dot) npc.lastHitTick = tickCount;
  if (npc.neutral) npc.provoked = true;
  if (o.splash) {
    for (const other of npcs) {
      if (other === npc || other.dead || (other.neutral && !other.provoked)) continue;
      if (cheb(other.x, other.y, npc.x, npc.y) <= o.splash) damageNpc(other, Math.ceil(dmg * 0.5), { xpSkill: o.xpSkill });
    }
  }
  if (npc.hp <= 0) killNpc(npc);
  if (player.target === npc.id) updateTargetFrame();
}

/* ---------- Loot rolls (tables live in data.js) ---------- */
function lootBand(level) { return level <= 7 ? 0 : level <= 13 ? 1 : level <= 21 ? 2 : 3; }
function rollLootTable(table, level) {
  const total = table.reduce((a, e) => a + e[1], 0);
  let r = Math.random() * total;
  for (const e of table) {
    if ((r -= e[1]) > 0) continue;
    if (!e[0]) return null;
    const pool = LOOT_TIERS[e[0]] ? LOOT_TIERS[e[0]][lootBand(level)] : [e[0]];
    const key = pool[Math.floor(Math.random() * pool.length)];
    const n = (e[2] || 1) + Math.floor(Math.random() * ((e[3] || e[2] || 1) - (e[2] || 1) + 1));
    return { key, n };
  }
  return null;
}
function rollKillLoot(npc) {
  const out = [];
  const tier = npc.boss ? 'boss' : (npc.special ? 'special' : 'normal');
  const fam = LOOT_FAMILY[npc.model] || 'scavenger';
  const main = rollLootTable(LOOT_TABLES[npc.boss ? 'boss' : fam], npc.level);
  if (main) out.push(main);
  if (npc.boss || npc.special) { const extra = rollLootTable(LOOT_TABLES.boss, npc.level); if (extra) out.push(extra); }
  if (npc.rareDrop && Math.random() < LOOT_RARE_CHANCE[tier]) out.push({ key: npc.rareDrop[Math.floor(Math.random() * npc.rareDrop.length)], n: 1, rare: true });
  if (npc.level >= 3 && Math.random() < LOOT_CACHE_CHANCE[tier]) out.push({ key: 'Starfall Cache', n: 1, rare: true });
  return out;
}

function killNpc(npc) {
  recordNamedDeath(npc);
  npc.dead = true; npc.inCombat = false; npc.provoked = false; npc.respawnTimer = npc.respawn;
  npc.deathT = performance.now(); npc.stunTicks = 0; npc.burnTicks = 0; npc.returning = false;
  if (player.target === npc.id) clearTarget();
  if (npc.training) {
    const sk = npc.lastHitSkill;
    const ev = ['Vanguard', 'Kinetic', 'Aegis'].includes(sk) ? 'drone-blade' : (sk === 'Marksman' ? 'drone-gunner' : (sk === 'Arcanistry' ? 'drone-artificer' : null));
    burst(npc.visX, tileTop(npc.x, npc.y) + 0.5, npc.visY, npc.color, 18, { speed: 2.5, up: 2 });
    playSound('hit');
    if (ev) campaignEvent(ev);
    return;
  }
  if (!npc.playerDmg) {
    addChatMessage(`The guards brought down the ${npc.name}.`, 'muted');
    burst(npc.visX, tileTop(npc.x, npc.y) + 0.8, npc.visY, npc.color, 22, { speed: 3, up: 3, life: 1, size: 0.35 });
    return;
  }
  const coins = 8 + Math.floor(Math.random() * (npc.coinMax || 20));
  player.coins += coins;
  player.kills++;
  recordQuestEvent('kill', npc);
  const top = tileTop(npc.x, npc.y) + 1.8;
  addSplat(npc.visX, top + 0.4, npc.visY, `+${coins} Credits`, 'coin');
  if (npc.drop && ITEMS[npc.drop]) dropGround(npc.drop, npc.x, npc.y);
  const loot = rollKillLoot(npc);
  for (const d of loot) for (let i = 0; i < d.n; i++) dropGround(d.key, npc.x, npc.y, d.rare);
  for (const d of loot.filter(d => d.rare)) addChatMessage(`Rare drop: ${npc.name} dropped ${d.key}!`, 'rare');
  if (loot.some(d => d.rare)) playSound('pickup');
  const common = loot.filter(d => !d.rare).map(d => d.n > 1 ? `${d.n} × ${d.key}` : d.key);
  if (common.length) addChatMessage(`Loot: ${common.join(', ')}.`, 'muted');
  const hunt = currentHunt();
  if (hunt && QUESTS[player.world.activeHunt].steps[0].target === npc.kindId) {
    gainXp('Huntmaster', 20 + npc.level * 3);
    if (questReady(player.world.activeHunt)) {
      completeQuest(player.world.activeHunt);
      addChatMessage(`Hunt complete! +${hunt.xp} Huntmaster XP and ${hunt.coins} Credits.`, 'good');
      showToast('Hunt complete', `+${hunt.coins} Credits`, 'quest');
    }
    markDirty('journal');
  }
  campaignOnKill(npc);
  const big = npc.boss || npc.special;
  burst(npc.visX, tileTop(npc.x, npc.y) + 0.8, npc.visY, npc.color, big ? 60 : 22, { speed: big ? 5 : 3, up: 3, life: 1, size: 0.35 });
  spawnShockwave(npc.visX, tileTop(npc.x, npc.y) + 0.05, npc.visY, npc.color, big ? 4 : 1.6, 0.6);
  if (big) playSound('explosion');
  addChatMessage(`Defeated ${npc.name}. +${coins} Credits.`, 'loot');
  if (player.target === npc.id) clearTarget();
  markDirty('bars');
}

function respawnNpc(npc) {
  if (npcPermanentlyDead(npc)) { npc.dead = true; return; }
  npc.dead = false; npc.hp = npc.maxHp; npc.x = npc.spawnX; npc.y = npc.spawnY; npc.visX = npc.x; npc.visY = npc.y;
  npc.inCombat = false; npc.atkCd = 0; npc.specialCounter = 0; npc.deathT = 0; npc.playerDmg = 0; npc.guardTarget = null; npc.returning = false;
}

/* ---------- Random encounters while travelling (data/wild.json "encounters") ---------- */
let encounterSeq = 50000, encounterCd = 30;
const activeEncounters = [];
function removeNpc(npc) {
  const i = npcs.indexOf(npc); if (i !== -1) npcs.splice(i, 1);
  removeNpcMesh(npc.id);
  if (player.target === npc.id) clearTarget();
}
function encounterSpot(dist) {
  for (let tries = 0; tries < 24; tries++) {
    const a = Math.random() * Math.PI * 2, d = dist + Math.random() * 4;
    const x = Math.round(player.x + Math.cos(a) * d), y = Math.round(player.y + Math.sin(a) * d);
    const [sx, sy] = snapTile(x, y, (p, q) => NATURAL_TILES.has(tileAt(p, q)) && isTileWalkable(p, q), 4);
    if (!isTileWalkable(sx, sy) || inTownBox(sx, sy, 6)) continue;
    const route = findPath(player.x, player.y, sx, sy, 0, { maxNodes: 6000 });
    if (route.length && route.length < dist * 2.5) return [sx, sy];
  }
  return null;
}
function spawnTemp(o) {
  const n = mkNpc(Object.assign({ id: encounterSeq++, respawn: 4, temp: true }, o));
  n.visX = n.x; n.visY = n.y; n.facing = 0;
  npcs.push(n);
  return n;
}
function startEncounter(def) {
  const spot = encounterSpot(11); if (!spot) return false;
  const [x, y] = spot, members = [];
  const free = (p, q) => isTileWalkable(p, q) && !npcs.some(n => !n.dead && n.x === p && n.y === q);
  if (def.named) {
    const nd = def.named, lvl = nd.level || 5;
    if (WORLD_RULES.permanentDeaths && player.world.dead[nd.sid]) return false;
    const n = spawnTemp({ sid: nd.sid, kindId: nd.sid, faction: nd.faction, name: nd.name, model: nd.model || 'citizen', color: nd.color || '#94a3b8', level: lvl, x, y,
      maxHp: 10 + lvl * 3, maxHit: Math.max(1, Math.round(lvl / 2.5)), neutral: !nd.hostile, named: true, desc: nd.desc, barks: [nd.bark || '...'],
      shop: nd.shop, wander: 1, coinMax: nd.hostile ? 160 : 20, drop: nd.hostile ? 'Starfall Cache' : undefined, range: nd.hostile ? 5 : 1, style: nd.hostile ? 'ranged' : 'melee' });
    if (nd.hostile) { n.ambush = true; n.aggroRange = 14; }
    members.push(n);
  }
  for (const [name, lo, hi] of def.group || []) {
    const count = lo + Math.floor(Math.random() * (hi - lo + 1));
    for (let i = 0; i < count; i++) {
      const [px, py] = snapTile(x + 2 + (i % 3), y - 1 + Math.floor(i / 3) * 2, free, 5);
      const n = cloneNpc(name, encounterSeq++, px, py); if (!n) continue;
      Object.assign(n, { temp: true, respawn: 4, ambush: true, aggroRange: 14, visX: px, visY: py, facing: 0 });
      npcs.push(n); members.push(n);
    }
  }
  if (!members.length) return false;
  activeEncounters.push({ def, members, rescued: false });
  addChatMessage(def.say, def.named && !def.named.hostile && !def.group ? 'accent' : 'warn');
  const lead = members[0];
  addOverheadBark(lead, def.bark || def.named?.bark || '!', def.named && !def.named.hostile ? '#a5f3fc' : '#fda4af');
  return true;
}
function encounterTick() {
  if (playerDead || !gameStarted) return;
  for (let i = activeEncounters.length - 1; i >= 0; i--) {
    const e = activeEncounters[i];
    const alive = e.members.filter(n => !n.dead && npcs.includes(n));
    // a rescued traveller thanks you once their attackers are down
    const named = e.def.named, who = alive.find(n => n.named && n.neutral);
    if (named?.rescue && who && !e.rescued && alive.every(n => n === who) && cheb(who.x, who.y, player.x, player.y) <= 8) {
      e.rescued = true; player.coins += named.rescue; markDirty('bars');
      addOverheadBark(who, 'Thank you, Starborn. Take this, it is all I have.', '#a5f3fc');
      addChatMessage(`${who.name} gives you ${named.rescue} Credits for the rescue.`, 'loot');
    }
    // leave the world once you have moved on
    if (!alive.length || alive.every(n => !n.inCombat && cheb(n.x, n.y, player.x, player.y) > 55)) {
      for (const n of alive) removeNpc(n);
      activeEncounters.splice(i, 1);
    }
  }
  if (--encounterCd > 0) return;
  encounterCd = 30 + Math.floor(Math.random() * 30);   // a roll every 18 to 36 seconds of travel
  if (activeEncounters.length >= 2 || inTownBox(player.x, player.y, 25) || player.target !== null || npcs.some(n => n.inCombat && !n.dead)) return;
  if (Math.random() > 0.45) return;
  // encounters can ask for a minimum combat level, so the dangerous ones don't ambush new players
  const list = ((GAME_DATA.wild.encounters || {})[getBiome(player.x, player.y)] || []).filter(e => !e.minCombat || getCombatLevel() >= e.minCombat);
  if (!list.length) return;
  let r = Math.random() * list.reduce((t, e) => t + (e.weight || 1), 0);
  const def = list.find(e => (r -= (e.weight || 1)) < 0) || list[0];
  startEncounter(def);
}

/* ---------- Enemy AI ---------- */
function occupiedSet(except) {
  const s = new Set();
  for (const n of npcs) if (!n.dead && n !== except) s.add(tKey(n.x, n.y));
  s.add(tKey(player.x, player.y));
  return s;
}
function stepToward(npc, tx, ty, range, maxNodes = 1600) {
  const path = findPath(npc.x, npc.y, tx, ty, range, { maxNodes, los: range > 1, occupied: occupiedSet(npc) });
  if (path.length) {
    const n = path[0];
    npc.x = n.x; npc.y = n.y;
    return true;
  }
  return false;
}
function animateNpc(npc, action, dur) { npc.anim = { action, start: performance.now(), dur: dur * 1000 }; }

function npcTick(npc) {
  if (npc.dead) { if (npcPermanentlyDead(npc)) return; if (--npc.respawnTimer <= 0) { if (npc.temp) removeNpc(npc); else respawnNpc(npc); } return; }
  if (npc.burnTicks > 0) {
    npc.burnTicks--;
    if (npc.burnTicks % 2 === 0) { damageNpc(npc, 1 + (Math.random() * 2 | 0), { dot: true, xpSkill: 'Arcanistry' }); if (npc.dead) return; }
  }
  const d = cheb(player.x, player.y, npc.x, npc.y);
  if (d > 40 && !npc.inCombat && !npc.returning && npc.guardTarget == null) return;
  if (npc.passive) { npc.inCombat = false; return; }
  if (npc.neutral && !npc.provoked && npc.role === 'guard' && guardTick(npc)) return;
  if (npc.barks && Math.random() < 0.01 && d < 14) addOverheadBark(npc, npc.barks[Math.floor(Math.random() * npc.barks.length)], npc.neutral ? '#a5f3fc' : '#fcd34d');
  const hostile = !npc.neutral || npc.provoked;
  if (hostile && !npc.inCombat && !npc.returning && !playerDead) {
    // RuneScape rule: creatures stop bothering you once you are more than twice their level
    const aggro = npc.boss || npc.special || npc.provoked || npc.ambush || getCombatLevel() <= npc.level * 2;
    if (aggro && d <= npc.aggroRange && hasLOS(npc.x, npc.y, player.x, player.y)) {
      npc.inCombat = true;
      npc.atkCd = 1;
      addOverheadBark(npc, npc.barks?.[0] || 'Target acquired!', '#fda4af');
      if (player.autoRetaliate && player.target === null && !player.task && !player.path.length) setTarget(npc);
    }
  }
  if (npc.inCombat) {
    // Leash: an enemy only gives up once you have stopped attacking it AND run more than 18 sectors away.
    // A wide home range (40) stops it following you across the world once you stop fighting.
    const beingHit = tickCount - (npc.lastHitTick ?? -99) <= 8;
    if (playerDead || (!beingHit && (d > 18 || cheb(npc.x, npc.y, npc.spawnX, npc.spawnY) > 40))) { npc.inCombat = false; npc.returning = true; npc.provoked = false; return; }
    if (npc.stunTicks > 0) { npc.stunTicks--; return; }
    if (npc.atkCd > 0) npc.atkCd--;
    if (npc.special && ++npc.specialCounter >= npc.special.every && d <= 9) {
      npc.specialCounter = 0; castSpecial(npc); npc.atkCd = Math.max(npc.atkCd, 2); return;
    }
    const inRange = d >= 1 && d <= npc.range && (npc.range === 1 || hasLOS(npc.x, npc.y, player.x, player.y));
    if (inRange) {
      npc.facing = Math.atan2(player.x - npc.x, player.y - npc.y);
      if (npc.atkCd <= 0) { npcAttack(npc); npc.atkCd = npc.atkSpeed; }
    } else if (stepToward(npc, player.x, player.y, npc.range)) npc.blocked = 0;
    else if ((npc.blocked = (npc.blocked || 0) + 1) >= 4) { npc.blocked = 0; npc.inCombat = false; npc.returning = true; npc.provoked = false; } // cannot reach you: back off home
  } else if (npc.returning) {
    // No regeneration: a wounded enemy stays wounded until it dies and respawns
    if (npc.x === npc.spawnX && npc.y === npc.spawnY) { npc.returning = false; npc.returnFails = 0; }
    else if (stepToward(npc, npc.spawnX, npc.spawnY, 0, 6000)) npc.returnFails = 0;
    else if ((npc.returnFails = (npc.returnFails || 0) + 1) >= 5 && d > 10) { npc.x = npc.spawnX; npc.y = npc.spawnY; npc.visX = npc.x; npc.visY = npc.y; npc.returning = false; npc.returnFails = 0; } // lost its way: slips home out of sight
  } else {
    if (npc.patrol && !npc.inConversation) {
      const pt = npc.patrol[npc.patrolIdx || 0];
      if (npc.x === pt[0] && npc.y === pt[1]) npc.patrolIdx = ((npc.patrolIdx || 0) + 1) % npc.patrol.length;
      else if (tickCount % 2 === 0 && !stepToward(npc, pt[0], pt[1], 0)) npc.patrolIdx = ((npc.patrolIdx || 0) + 1) % npc.patrol.length;
    } else if (!npc.stationary && !npc.inConversation && Math.random() < 0.14) {
      const [dx, dy] = DIRS8[Math.floor(Math.random() * 4)];
      const nx = npc.x + dx, ny = npc.y + dy, wr = npc.wander || 2;
      if (Math.abs(nx - npc.spawnX) <= wr && Math.abs(ny - npc.spawnY) <= wr && isTileWalkable(nx, ny) && !occupiedSet(npc).has(tKey(nx, ny))) { npc.x = nx; npc.y = ny; }
    }
  }
}

/* Guards step in when something hostile is fighting you nearby */
const GUARD_CALLS = ['Hostile in the city!', 'Stand aside, Starborn!', 'Engaging!', 'Not on my watch!'];
function guardTick(g) {
  let foe = g.guardTarget != null ? npcById(g.guardTarget) : null;
  if (foe && (foe.dead || cheb(g.x, g.y, g.spawnX, g.spawnY) > 16 || !foe.inCombat)) { foe = null; g.guardTarget = null; g.returning = true; }
  if (!foe) {
    if (playerDead || cheb(g.x, g.y, player.x, player.y) > 14) return false;
    foe = npcs.find(n => !n.dead && !n.neutral && !n.passive && n.inCombat && cheb(n.x, n.y, g.x, g.y) <= 9 && cheb(n.x, n.y, player.x, player.y) <= 10);
    if (!foe) return false;
    g.guardTarget = foe.id; g.returning = false;
    addOverheadBark(g, GUARD_CALLS[Math.floor(Math.random() * GUARD_CALLS.length)], '#fcd34d');
  }
  const dd = cheb(g.x, g.y, foe.x, foe.y);
  if (dd <= 1) {
    g.facing = Math.atan2(foe.x - g.x, foe.y - g.y);
    if (--g.atkCd <= 0) {
      g.atkCd = g.atkSpeed;
      animateNpc(g, 'melee', 0.5);
      const dmg = Math.random() < 0.75 ? 1 + Math.floor(Math.random() * g.maxHit) : 0;
      setTimeout(() => { if (!foe.dead) damageNpc(foe, dmg, { byNpc: true }); }, 220);
    }
  } else stepToward(g, foe.x, foe.y, 1);
  return true;
}

function rollNpcDamage(npc) {
  const def = getArmourDef();
  const block = Math.min(0.45, def * 0.011);
  if (Math.random() < block) return 0;
  return Math.floor(Math.random() * (npc.maxHit + 1));
}

function npcAttack(npc) {
  const dmg = rollNpcDamage(npc);
  if (npc.style === 'melee') {
    animateNpc(npc, 'melee', 0.5);
    setTimeout(() => { if (!npc.dead && cheb(player.x, player.y, npc.x, npc.y) <= 1) damagePlayer(dmg, npc); }, 220);
    return;
  }
  animateNpc(npc, npc.model === 'raider' ? 'shoot' : 'cast', 0.5);
  const from = new THREE.Vector3(); entityAimPos(npc, from); from.y += 0.25;
  const kind = npc.style === 'ranged' ? 'bolt' : (npc.style === 'fire' ? 'fire' : 'spell');
  const color = npc.style === 'ranged' ? '#f43f5e' : (npc.style === 'fire' ? '#f97316' : npc.color);
  spawnProjectile({ from, target: player, kind, color, onHit: () => damagePlayer(dmg, npc) });
  playSound(npc.style === 'ranged' ? 'pistol' : 'enemyBolt');
}

function damagePlayer(dmg, src, ignoreReduction = false) {
  if (playerDead) return;
  if (!ignoreReduction && dmg > 0 && src && src.style === 'melee' && hasSpec('Duellist') && Math.random() < 0.15) {
    addSplat(player.visX, tileTop(player.x, player.y) + 1.9, player.visY, 'PARRY', 'miss'); playSound('melee'); return;
  }
  if (!ignoreReduction && player.doctrine === 'Defensive' && dmg > 0) dmg = Math.max(0, dmg - 1);
  player.hp = Math.max(0, player.hp - dmg);
  player.lastCombatTick = tickCount;
  addSplat(player.visX, tileTop(player.x, player.y) + 1.9, player.visY, dmg > 0 ? String(dmg) : 'BLOCK', dmg > 0 ? 'hurt' : 'miss');
  if (dmg > 0) { playSound('hurt'); animatePlayer('hurt', 0.3); pulseDamageVignette(Math.min(1, dmg / Math.max(4, player.maxHp * 0.3))); }
  if (player.autoRetaliate && player.target === null && !player.task && !player.path.length && src && !src.dead && src.maxHp) setTarget(src);
  markDirty('bars');
  if (player.hp <= 0) playerDeath();
}

function castSpecial(npc) {
  const sp = npc.special.type;
  animateNpc(npc, 'cast', 1.0);
  playSound('warn');
  if (sp === 'shatter') {
    addOverheadBark(npc, 'SEISMIC SHATTER.', '#6ee7b7');
    addHazard(npc.x, npc.y, 2, 3, 6, 12, '#34d399', npc, 'shatter');
  } else if (sp === 'meteor') {
    addOverheadBark(npc, 'Fall, burning sky!', '#fdba74');
    addHazard(player.x, player.y, 1, 3, 5, 11, '#f97316', npc, 'meteor');
    for (let i = 0; i < 2; i++) addHazard(player.x + (Math.random() * 7 | 0) - 3, player.y + (Math.random() * 7 | 0) - 3, 1, 4, 5, 11, '#f97316', npc, 'meteor');
  } else if (sp === 'flare') {
    addOverheadBark(npc, '*CORONAL FLARE*', '#fde047');
    addHazard(player.x, player.y, 1, 3, 9, 17, '#facc15', npc, 'flare');
    const a = Math.random() * Math.PI * 2;
    addHazard(player.x + Math.round(Math.cos(a) * 3), player.y + Math.round(Math.sin(a) * 3), 1, 4, 9, 17, '#facc15', npc, 'flare');
  }
}

function addHazard(x, y, radius, delay, dmgMin, dmgMax, color, src, kind) {
  x = clamp(x, 0, WORLD_COLS - 1); y = clamp(y, 0, WORLD_ROWS - 1);
  const h = { x, y, radius, ticks: delay, total: delay, dmgMin, dmgMax, color, src, kind, start: performance.now() };
  h.mesh = createHazardMesh(h);
  hazards.push(h);
}

function hazardTick() {
  for (let i = hazards.length - 1; i >= 0; i--) {
    const h = hazards[i];
    if (--h.ticks > 0) continue;
    const top = tileTop(h.x, h.y);
    if (h.kind === 'flare' && h.src && !h.src.dead) {
      const from = new THREE.Vector3(); entityAimPos(h.src, from); from.y += 0.4;
      spawnBeam(from, new THREE.Vector3(h.x, top + 0.1, h.y), h.color, 0.12, 0.35);
    }
    if (h.kind === 'meteor') spawnBeam(new THREE.Vector3(h.x + 2, 14, h.y - 2), new THREE.Vector3(h.x, top, h.y), h.color, 0.18, 0.3);
    burst(h.x, top + 0.3, h.y, h.color, 40, { speed: 4.5, up: 3.5, life: 0.9, size: 0.4 });
    spawnShockwave(h.x, top + 0.05, h.y, h.color, h.radius + 1.2, 0.6);
    flash(h.x, top + 0.5, h.y, h.color, 5);
    playSound('explosion');
    if (!playerDead && cheb(player.x, player.y, h.x, h.y) <= h.radius) {
      const dmg = h.dmgMin + Math.floor(Math.random() * (h.dmgMax - h.dmgMin + 1));
      damagePlayer(dmg, h.src, true);
      shakeCamera(0.35);
    } else if (cheb(player.x, player.y, h.x, h.y) <= h.radius + 3) shakeCamera(0.15);
    scene.remove(h.mesh);
    hazards.splice(i, 1);
  }
}
function clearHazards() { for (const h of hazards) scene.remove(h.mesh); hazards.length = 0; }

function playerDeath() {
  playerDead = true;
  playSound('death');
  const lost = Math.floor(player.coins * 0.1);
  player.coins -= lost;
  player.path = []; player.task = null; clearTarget();
  for (const n of npcs) if (n.inCombat) { n.inCombat = false; n.returning = true; n.provoked = false; }
  clearHazards();
  burst(player.visX, tileTop(player.x, player.y) + 1, player.visY, 0xf43f5e, 50, { speed: 4, up: 3, life: 1.2 });
  showDeathOverlay(lost);
  markDirty('journal');
  setTimeout(() => {
    player.x = START_POS.x; player.y = START_POS.y; player.visX = START_POS.x; player.visY = START_POS.y;
    player.hp = player.maxHp; player.energy = 100;
    playerDead = false;
    onPlayerTileChanged();
    hideDeathOverlay();
    burst(START_POS.x, 1, START_POS.y, 0x67e8f9, 40, { speed: 2, up: 4, life: 1.2 });
    addChatMessage('Phase-recall complete. You wake in the Solstice Bastion.', 'accent');
    markDirty('bars');
  }, 2800);
}

/* ---------- Abilities ---------- */
function abilityCooldownLeft(id) { return Math.max(0, (player.abilityReady[id] || 0) - performance.now()); }

function findAbilityTarget(range) {
  let npc = player.target !== null ? npcById(player.target) : null;
  if (npc && !npc.dead && cheb(player.x, player.y, npc.x, npc.y) <= range && hasLOS(player.x, player.y, npc.x, npc.y)) return npc;
  if (hoverNpcId !== null) { const h = npcById(hoverNpcId); if (h && !h.dead && (!h.neutral || h.provoked) && cheb(player.x, player.y, h.x, h.y) <= range && hasLOS(player.x, player.y, h.x, h.y)) return h; }
  let best = null, bd = 99;
  for (const n of npcs) {
    if (n.dead || (n.neutral && !n.provoked)) continue;
    const d = cheb(player.x, player.y, n.x, n.y);
    if (d <= range && d < bd && hasLOS(player.x, player.y, n.x, n.y)) { bd = d; best = n; }
  }
  return best;
}

function useAbility(id) {
  if (!gameStarted || playerDead) return;
  const ab = abilityDef(id);
  if (!ab) return;
  if (lvl(ab.req[0]) < ab.req[1]) { addChatMessage(`${ab.name} needs ${ab.req[0]} ${ab.req[1]}.`, 'warn'); playSound('deny'); return; }
  if (abilityCooldownLeft(id) > 0) { playSound('deny'); return; }
  const c = ab.cost;
  if (c.cells && player.cells < c.cells) { addChatMessage(`${ab.name} needs ${c.cells} Aether Cell${c.cells > 1 ? 's' : ''}.`, 'warn'); playSound('deny'); return; }
  const top = tileTop(player.x, player.y);
  if (id === 'ion') {
    const npc = findAbilityTarget(ab.range);
    if (!npc) { addChatMessage(`No hostile target within ${ab.range} sectors.`, 'warn'); playSound('deny'); return; }
    player.cells -= c.cells;
    player.facing = Math.atan2(npc.x - player.x, npc.y - player.y);
    if (player.target !== npc.id) setTarget(npc);
    animatePlayer('cast', 0.45);
    const cowl = ITEMS[player.equipment.head]?.arc || 0;
    const from = muzzlePos(new THREE.Vector3());
    const max = 3 + Math.floor(lvl('Arcanistry') / 3) + cowl;
    const hit = Math.random() < clamp(0.7 + (lvl('Arcanistry') - npc.level) * 0.03, 0.35, 0.97);
    const dmg = hit ? Math.max(1, Math.round((1 + Math.floor(Math.random() * max)) * typeMult(npc, 'emp'))) : 0;
    spawnProjectile({ from, target: npc, kind: 'ion', color: '#a5f3fc', onHit: () => damageNpc(npc, dmg, { xpSkill: 'Arcanistry', stun: hit ? 3 : 0 }) });
    playSound('ion');
  } else if (id === 'cleave' || id === 'aimed' || id === 'turret') {
    if (!useSignature(id, ab, top)) return;
  } else if (id === 'overdrive') {
    if (player.overdriveArmed) { player.overdriveArmed = false; addChatMessage('Overdrive disarmed.', 'muted'); }
    else if (player.energy < 50) { addChatMessage('Overdrive needs 50% charge.', 'warn'); playSound('deny'); return; }
    else { player.overdriveArmed = true; addChatMessage('Overdrive armed. Your next hit is empowered.', 'accent'); playSound('magic'); burst(player.visX, top + 1, player.visY, 0x67e8f9, 16, { speed: 1.5, up: 2 }); }
  } else if (id === 'dash') {
    let tx, ty;
    if (hoverTile && cheb(player.x, player.y, hoverTile.x, hoverTile.y) <= 6 && !(hoverTile.x === player.x && hoverTile.y === player.y) && !isTouchDevice) { tx = hoverTile.x; ty = hoverTile.y; }
    else { tx = Math.round(player.x + Math.sin(player.facing) * 4); ty = Math.round(player.y + Math.cos(player.facing) * 4); }
    const dest = dashDestination(tx, ty, 4);
    if (!dest) { addChatMessage('Nowhere to dash.', 'warn'); playSound('deny'); return; }
    const fromX = player.visX, fromY = player.visY;
    for (let i = 0; i <= 12; i++) { const k = i / 12; emitParticle(fromX + (dest.x - fromX) * k, top + 0.4 + Math.random() * 1.2, fromY + (dest.y - fromY) * k, 0, 0.3, 0, 0.5, 0.35, 0x67e8f9, 0, 0.9); }
    player.facing = Math.atan2(dest.x - player.x, dest.y - player.y);
    player.x = dest.x; player.y = dest.y; player.visX = dest.x; player.visY = dest.y; player.path = [];
    burst(dest.x, top + 0.8, dest.y, 0x67e8f9, 18, { speed: 2.5, up: 1.5, life: 0.5 });
    playSound('dash');
    gainXp('Parkour', 12);
    onPlayerTileChanged();
  }
  player.abilityReady[id] = performance.now() + (id === 'dash' && hasSpec('Shadowstep') ? 5 : ab.cd) * TICK_MS;
  if (id === 'dash' && hasSpec('Shadowstep')) player.shadowUntil = performance.now() + 3000;
  markDirty('bars'); markDirty('abilities');
}

function hostileNear(x, y, r) { return npcs.filter(n => !n.dead && (!n.neutral || n.provoked) && cheb(x, y, n.x, n.y) <= r); }

function useSignature(sig, ab, top) {
  if (sig === 'cleave') {
    if (!player.equipment.primary) { addChatMessage('Cleave needs a melee weapon.', 'warn'); playSound('deny'); return false; }
    const foes = hostileNear(player.x, player.y, 1);
    if (!foes.length) { addChatMessage('Cleave needs an enemy next to you.', 'warn'); playSound('deny'); return false; }
    const st = weaponStats('primary');
    setVisualWeapon('primary');
    animatePlayer('melee', 0.5); playSound('melee');
    spawnShockwave(player.visX, top + 0.05, player.visY, st.it?.glow || 0xfbbf24, 1.8, 0.4);
    setTimeout(() => {
      for (const n of foes) {
        const hit = Math.random() < clamp(0.7 + (lvl('Vanguard') - n.level) * 0.03, 0.3, 0.97);
        const dmg = hit ? Math.max(1, Math.round((1 + Math.floor(Math.random() * Math.ceil(st.maxHit * 1.2))) * typeMult(n, st.it?.dmgType || 'kinetic') * (hasSpec('Juggernaut') ? 1.3 : 1))) : 0;
        damageNpc(n, dmg, { xpSkill: doctrineSkill() });
      }
      if (player.target === null) setTarget(foes[0]);
    }, 200);
    player.attackCd = Math.max(player.attackCd, 2);
    return true;
  }
  if (sig === 'aimed') {
    const it = ITEMS[player.equipment.sidearm];
    if (!it || it.skill || !hasAmmoFor(it)) { addChatMessage('Aimed Shot needs a loaded gun in your sidearm slot.', 'warn'); playSound('deny'); return false; }
    const reach = it.range + 2 + (hasSpec('Sharpshooter') ? 2 : 0);
    const npc = findAbilityTarget(reach);
    if (!npc) { addChatMessage(`No target within ${reach} sectors.`, 'warn'); playSound('deny'); return false; }
    if (it.ammo) { if (it.ammo === 'cells') player.cells -= it.ammoCost || 1; else player.slugs -= it.ammoCost || 1; }
    setVisualWeapon('sidearm'); animatePlayer('shoot', 0.5);
    player.facing = Math.atan2(npc.x - player.x, npc.y - player.y);
    if (player.target !== npc.id) setTarget(npc);
    const st = weaponStats('sidearm');
    const hit = Math.random() < clamp(0.85 + (lvl('Marksman') - npc.level) * 0.02, 0.5, 0.98);
    const dmg = hit ? Math.max(1, Math.round((1 + Math.floor(Math.random() * st.maxHit)) * 1.8 * typeMult(npc, it.dmgType || 'kinetic') * (hasSpec('Sharpshooter') ? 1.2 : 1))) : 0;
    const from = muzzlePos(new THREE.Vector3()), tgt = new THREE.Vector3(); entityAimPos(npc, tgt);
    spawnBeam(from, tgt, it.glow || '#fbbf24', 0.06, 0.32); flash(from.x, from.y, from.z, it.glow || '#fbbf24', 3);
    playSound('rail');
    damageNpc(npc, dmg, { xpSkill: 'Marksman', crit: dmg > 0 });
    player.attackCd = Math.max(player.attackCd, 2);
    return true;
  }
  if (sig === 'turret') {
    const spot = DIRS8.map(([dx, dy]) => ({ x: player.x + dx, y: player.y + dy })).find(p => isTileWalkable(p.x, p.y) && !occupiedSet(null).has(tKey(p.x, p.y)) && !turrets.some(t => t.x === p.x && t.y === p.y));
    if (!spot) { addChatMessage('No room to deploy a turret here.', 'warn'); playSound('deny'); return false; }
    player.cells -= ab.cost.cells || 0;
    const max = (lvl('Arcanistry') >= 30 ? 2 : 1) + (hasSpec('Dronewright') ? 1 : 0);
    while (turrets.length >= max) removeTurret(turrets[0]);
    deployTurret(spot.x, spot.y);
    animatePlayer('cast', 0.5); playSound('magic');
    return true;
  }
  return false;
}

/* Artificer sentry turrets */
const turrets = [];
function deployTurret(x, y) {
  const g = new THREE.Group();
  const top = tileTop(x, y);
  g.add(mesh(G.cyl(0.32, 0.4, 0.3, 8), smat('#334155', 0.4, 0.7), 0, 0.15, 0));
  g.add(mesh(G.cyl(0.08, 0.1, 0.5, 6), smat('#475569', 0.4, 0.7), 0, 0.5, 0));
  const head = new THREE.Group(); head.position.y = 0.8; head.name = 'head';
  head.add(mesh(G.box(0.34, 0.22, 0.4), smat('#1e293b', 0.4, 0.6), 0, 0, 0));
  head.add(mesh(G.cyl(0.04, 0.04, 0.5, 6).rotateX(Math.PI / 2), smat('#94a3b8', 0.3, 0.8), 0.08, 0, 0.35));
  head.add(mesh(G.cyl(0.04, 0.04, 0.5, 6).rotateX(Math.PI / 2), smat('#94a3b8', 0.3, 0.8), -0.08, 0, 0.35));
  head.add(mesh(G.box(0.2, 0.05, 0.02), gmat('#c084fc'), 0, 0.05, 0.21));
  g.add(head);
  const gl = makeGlow(0xc084fc, 1.2, 0.7); gl.position.y = 0.8; g.add(gl);
  g.position.set(x, top, y);
  scene.add(g);
  burst(x, top + 0.6, y, 0xc084fc, 16, { speed: 1.5, up: 2 });
  turrets.push({ x, y, until: tickCount + (hasSpec('Sapper') ? 45 : 30), cd: 1, mesh: g, head });
  objectBlock.add(tKey(x, y)); walkGrid[tKey(x, y)] = 0;
}
function removeTurret(t) {
  scene.remove(t.mesh);
  turrets.splice(turrets.indexOf(t), 1);
  rebuildObjectBlock();
  for (const o of turrets) objectBlock.add(tKey(o.x, o.y));
}
function turretTick() {
  for (const t of turrets.slice()) {
    if (tickCount >= t.until) { burst(t.x, tileTop(t.x, t.y) + 0.6, t.y, 0x94a3b8, 10); removeTurret(t); continue; }
    if (--t.cd > 0) continue;
    const foe = hostileNear(t.x, t.y, 6).filter(n => hasLOS(t.x, t.y, n.x, n.y)).sort((a, b) => cheb(t.x, t.y, a.x, a.y) - cheb(t.x, t.y, b.x, b.y))[0];
    if (!foe) continue;
    t.cd = 2;
    t.head.rotation.y = Math.atan2(foe.x - t.x, foe.y - t.y);
    const max = Math.round((2 + Math.floor(lvl('Arcanistry') / 4)) * (hasSpec('Sapper') ? 1.4 : 1));
    const dmg = Math.random() < clamp(0.7 + (lvl('Arcanistry') - foe.level) * 0.025, 0.3, 0.95) ? Math.max(1, Math.round((1 + Math.floor(Math.random() * max)) * typeMult(foe, 'kinetic'))) : 0;
    const from = new THREE.Vector3(t.x, tileTop(t.x, t.y) + 0.85, t.y);
    spawnProjectile({ from, target: foe, kind: 'bolt', color: '#c084fc', onHit: () => damageNpc(foe, dmg, { xpSkill: 'Arcanistry', small: dmg === 0 }) });
    playSound('pistol');
    foe.inCombat = true;
  }
}

function dashDestination(tx, ty, maxSteps) {
  let best = null;
  const dx = tx - player.x, dy = ty - player.y;
  const steps = Math.max(Math.abs(dx), Math.abs(dy));
  if (!steps) return null;
  const n = Math.min(maxSteps, steps);
  for (let i = 1; i <= n; i++) {
    const x = Math.round(player.x + dx * i / steps), y = Math.round(player.y + dy * i / steps);
    if (!isTileWalkable(x, y) || map[y][x] === 8) break;
    if (occupiedSet(null).has(tKey(x, y)) && !(x === player.x && y === player.y)) break;
    best = { x, y };
  }
  return best;
}

/* ---------- Player animation hook ---------- */
function animatePlayer(action, dur) { playerAnim = { action, start: performance.now(), dur: dur * 1000 }; }

function setVisualWeapon(slot) {
  if (player.visualSlot === slot) return;
  player.visualSlot = slot;
  syncPlayerEquipmentVisuals();
}

/* ---------- Tick ---------- */
function gameTick() {
  tickCount++;
  if (player.energy < 100) player.energy = Math.min(100, player.energy + 1);
  if (player.tempStrTicks > 0 && --player.tempStrTicks <= 0) { player.tempStr = 0; addChatMessage('Your stim wears off.', 'muted'); }
  if (player.waypoint && cheb(player.x, player.y, player.waypoint.x, player.waypoint.y) <= 2) { addChatMessage(`You reach ${player.waypoint.label}.`, 'accent'); player.waypoint = null; }

  for (const obj of worldObjects) {
    if (obj.depleted && --obj.respawnTimer <= 0) {
      obj.depleted = false;
      if (obj.tempCampfire) removeWorldObject(obj);
    }
  }
  for (const obj of sceneryFelled) if (--obj.respawnTimer <= 0) { obj.depleted = false; setSceneryTreeFelled(obj, false); sceneryFelled.delete(obj); }
  for (let i = groundItems.length - 1; i >= 0; i--) {
    const gi = groundItems[i];
    if (gi.hidden && --gi.timer <= 0) gi.hidden = false;
    if (!gi.respawnSpot && gi.ttl !== undefined && --gi.ttl <= 0) { removeGroundItemMesh(gi); groundItems.splice(i, 1); }
  }
  for (let i = overheadBarks.length - 1; i >= 0; i--) if (--overheadBarks[i].ttl <= 0) overheadBarks.splice(i, 1);

  for (const npc of npcs.slice()) npcTick(npc);
  encounterTick();
  hazardTick();
  turretTick();
  if (!playerDead) { playerTaskTick(); playerCombatTick(); }
  if (tickCount % 80 === 0) saveGame(false);
  markDirty('bars');
}

function removeWorldObject(obj) {
  const m = objectMeshes.get(obj.id);
  if (m) scene.remove(m);
  objectMeshes.delete(obj.id);
  const idx = worldObjects.indexOf(obj);
  if (idx !== -1) worldObjects.splice(idx, 1);
  rebuildObjectBlock();
}

/* ---------- Tasks (gathering, talking, looting) ---------- */
function startTask(task) {
  player.target = null; updateTargetFrame();
  player.task = task;
  player.gatherCd = 0;
  if (task.type === 'ground') { const gi = groundItems.find(g => g.id === task.id); if (gi) player.path = routeTo(gi.x, gi.y, 0); }
  else if (task.type === 'object') { const o = objById(task.id); if (o) player.path = routeTo(o.x, o.y, 1); }
  else { const n = npcById(task.id); if (n) player.path = routeTo(n.x, n.y, 1); }
}

function playerTaskTick() {
  const task = player.task;
  if (!task) return;
  if (task.type === 'ground') {
    const gi = groundItems.find(g => g.id === task.id && !g.hidden);
    if (!gi) { player.task = null; return; }
    if (player.x === gi.x && player.y === gi.y) {
      // take everything lying on this sector, not just the item clicked
      const pile = [gi, ...groundItems.filter(g => g !== gi && !g.hidden && !g.respawnSpot && g.x === gi.x && g.y === gi.y)];
      const got = [];
      for (const g of pile) {
        if (!addItem(g.itemKey, got.length > 0)) break;
        got.push(g.itemKey);
        if (g.respawnSpot) { g.hidden = true; g.timer = 24; }
        else { removeGroundItemMesh(g); groundItems.splice(groundItems.indexOf(g), 1); }
      }
      if (got.length) {
        playSound('pickup');
        const counts = {}; for (const k of got) counts[k] = (counts[k] || 0) + 1;
        addChatMessage(`Picked up ${Object.entries(counts).map(([k, n]) => n > 1 ? `${n} × ${k}` : k).join(', ')}.`, pile.some(g => g.rare && got.includes(g.itemKey)) ? 'rare' : 'muted');
        if (got.length < pile.length) addChatMessage('Your pack is full. The rest is still on the ground.', 'warn');
      }
      player.task = null;
    } else if (!player.path.length) {
      player.path = routeTo(gi.x, gi.y, 0);
      if (!player.path.length) player.task = null;
    }
    return;
  }
  if (task.type === 'object') {
    const obj = objById(task.id);
    if (!obj || obj.depleted || isObjHidden(obj)) { player.task = null; return; }
    if (cheb(player.x, player.y, obj.x, obj.y) <= 1) {
      if (player.path.length) stopPlayer();
      player.facing = Math.atan2(obj.x - player.x, obj.y - player.y);
      if (player.gatherCd > 0) { player.gatherCd--; return; }
      handleObjectInteraction(obj);
    } else if (!player.path.length) {
      player.path = routeTo(obj.x, obj.y, 1);
      if (!player.path.length) { addChatMessage(`You cannot reach the ${obj.name}.`, 'warn'); player.task = null; }
    }
    return;
  }
  const npc = npcById(task.id);
  if (!npc || npc.dead) { player.task = null; return; }
  if (cheb(player.x, player.y, npc.x, npc.y) <= 1) {
    if (player.path.length) stopPlayer();
    player.facing = Math.atan2(npc.x - player.x, npc.y - player.y);
    npc.facing = Math.atan2(player.x - npc.x, player.y - npc.y);
    if (task.type === 'talk') { if (task.then) task.then(); else talkTo(npc); }
    else if (task.type === 'pickpocket') pickpocket(npc);
    player.task = null;
  } else if (!player.path.length || task.lastKey !== tKey(npc.x, npc.y)) {
    task.lastKey = tKey(npc.x, npc.y);
    player.path = routeTo(npc.x, npc.y, 1);
  }
}

function talkTo(npc) {
  if (npc.shop && !npc.dlg) { addOverheadBark(npc, npc.barks?.[0] || 'Take a look.', '#fcd34d'); openShopModal(npc.shop); return; }
  if (npc.dlg || npc.role) { openConversation(npc); return; }
  if (campaignOnTalk(npc)) return;
  const line = npc.barks ? npc.barks[Math.floor(Math.random() * npc.barks.length)] : 'Greetings, Starborn.';
  addOverheadBark(npc, line, '#a5f3fc');
  addChatMessage(`${npc.name}: "${line}"`, 'npc');
}

function pickpocket(npc) {
  const req = npc.pickpocketLvl || 1;
  if (!npc.pickpocketLvl) { addChatMessage(`The ${npc.name} has nothing worth taking.`, 'muted'); return; }
  if (lvl('Infiltration') < req) { addChatMessage(`You need Infiltration ${req} to pick ${npc.name}'s pocket.`, 'warn'); return; }
  animatePlayer('melee', 0.3);
  if (Math.random() < 0.72) {
    gainXp('Infiltration', npc.pickpocketXp || 32);
    if (npc.pickpocketHerb) {
      const herb = ['Silverleaf Frond', 'Moonbloom Petal', 'Solaris Lotus'][Math.floor(Math.random() * 3)];
      if (addItem(herb)) addChatMessage(`You lift a ${herb} from the pouch.`, 'good');
    } else {
      const stolen = 12 + Math.floor(Math.random() * 16);
      player.coins += stolen;
      addSplat(npc.visX, tileTop(npc.x, npc.y) + 2, npc.visY, `+${stolen} Credits`, 'coin');
      addChatMessage(`You lift ${stolen} Solaris Credits.`, 'loot');
    }
  } else {
    damagePlayer(2, null, true);
    addOverheadBark(npc, 'Hands off!', '#fda4af');
    addChatMessage(`Caught! ${npc.name} jolts you with a shock baton.`, 'warn');
  }
}

function handleObjectInteraction(obj) {
  const t = obj.type;
  const top = tileTop(obj.x, obj.y);
  if (t === 'starshard' || (t === 'rc_altar' && currentStep()?.obj === obj.id)) { if (campaignOnInteract(obj)) { player.task = null; return; } }
  if (t === 'starshard') { addChatMessage('The shard is held fast. Follow the campaign to claim it.', 'muted'); player.task = null; return; }
  if (t === 'bank') { openBankModal(); player.task = null; return; }
  if (t === 'stall') { openShopModal(obj.shop || 'quartermaster'); player.task = null; return; }
  if (t === 'anvil') { openAnvilModal(); player.task = null; return; }
  if (t === 'slayer_master') { assignNewSlayerTask(); player.task = null; return; }
  if (t === 'obelisk') {
    addChatMessage('Starfall Obelisk: "To the first Starborn, who caught a falling star and would not let it break."', 'npc');
    if (!player.lore.includes('obelisk')) player.lore.push('obelisk');
    player.task = null; return;
  }
  if (t === 'altar') {
    // The Starborn Reliquary: the order's legends, one line at a time
    const LEGENDS = [
      'Reliquary inscription: "Valerium was one union under many suns, and Vaelor bore its name."',
      'Reliquary inscription: "The relays spoke between the stars and showed the ships where every world would be."',
      'Reliquary inscription: "Sol cast the Heart into the dark rather than see it chained."',
      'Reliquary inscription: "When the Heart returns, the silence ends. So the Starborn keep the story until it does."'
    ];
    const k = (player.world.flags.legend || 0) % LEGENDS.length;
    player.world.flags.legend = k + 1;
    addChatMessage(LEGENDS[k], 'npc');
    burst(obj.x, top + 1.3, obj.y, 0xc4b5fd, 14, { speed: 1.2, up: 2, life: 0.8 });
    player.task = null; return;
  }
  if (t === 'rc_altar') {
    const count = removeItems('Raw Aether Crystal', 99);
    if (!count) addChatMessage('Bring Raw Aether Crystals to condense Aether Cells. Crystal pillars stand in Mistwood, Astraea, Sector Zero, Deepcore and near the crater.', 'warn');
    else {
      player.cells += count * 5;
      playSound('magic');
      burst(obj.x, top + 3.6, obj.y, 0x22d3ee, 30, { speed: 2, up: 2, life: 1 });
      gainXp('Shardweaving', count * 42);
      addChatMessage(`You condense ${count} crystals into ${count * 5} Aether Cells.`, 'accent');
    }
    player.task = null; return;
  }
  if (t === 'zipline' || t === 'agility_wall' || t === 'agility_vent') {
    if (lvl('Parkour') < obj.reqLvl) { addChatMessage(`You need Parkour ${obj.reqLvl} for the ${obj.name}.`, 'warn'); player.task = null; return; }
    burst(player.visX, tileTop(player.x, player.y) + 1, player.visY, 0x67e8f9, 16, { speed: 2, up: 2 });
    player.x = obj.destX; player.y = obj.destY; player.visX = obj.destX; player.visY = obj.destY; player.path = [];
    playSound('dash');
    gainXp('Parkour', obj.xp);
    addChatMessage(`You clear the ${obj.name}.`, 'good');
    onPlayerTileChanged();
    player.task = null; return;
  }
  if (t === 'tea_stall' || t === 'silk_stall' || t === 'gem_stall') {
    const req = t === 'gem_stall' ? 12 : (t === 'silk_stall' ? 5 : 1);
    const loot = t === 'gem_stall' ? 'Nova Star-Ruby' : (t === 'silk_stall' ? 'Mirage Weave' : 'Ambrosia Nectar');
    const xp = t === 'gem_stall' ? 105 : (t === 'silk_stall' ? 60 : 32);
    if (lvl('Infiltration') < req) { addChatMessage(`You need Infiltration ${req} for the ${obj.name}.`, 'warn'); player.task = null; return; }
    if (addItem(loot)) { playSound('pickup'); gainXp('Infiltration', xp); addChatMessage(`You quietly take ${loot}.`, 'loot'); obj.depleted = true; obj.respawnTimer = 6; }
    player.task = null; return;
  }
  if (t === 'herb_patch') {
    const herbs = ['Silverleaf Frond', 'Moonbloom Petal', 'Solaris Lotus'];
    const maxIdx = lvl('Bio-Synthesis') >= 12 ? 3 : (lvl('Bio-Synthesis') >= 6 ? 2 : 1);
    const picked = herbs[Math.floor(Math.random() * maxIdx)];
    animatePlayer('chop', 0.4);
    if (addItem(picked)) { playSound('chop'); burst(obj.x, top + 0.4, obj.y, 0x4ade80, 10); gainXp('Bio-Synthesis', 28); addChatMessage(`You harvest a ${picked}.`, 'good'); obj.depleted = true; obj.respawnTimer = 7; }
    player.task = null; return;
  }
  if (t === 'tree' || t === 'oak_tree' || t === 'willow_tree' || t === 'yew_tree') {
    const spec = { tree: [1, 'Timber: Duskpine', 32], oak_tree: [5, 'Timber: Ironbark', 55], willow_tree: [10, 'Timber: Gloamwillow', 85], yew_tree: [15, 'Timber: Starwood', 135] }[t];
    if (lvl('Timbercraft') < spec[0]) { addChatMessage(`You need Timbercraft ${spec[0]} to cut ${obj.name}.`, 'warn'); player.task = null; return; }
    player.gatherCd = 1;
    animatePlayer('chop', 0.5); playSound('chop');
    burst(obj.x, top + 0.8, obj.y, 0xa87038, 6, { speed: 1.5, up: 1.5, size: 0.15 });
    if (Math.random() < 0.45 + lvl('Timbercraft') * 0.01) {
      if (addItem(spec[1])) { gainXp('Timbercraft', spec[2]); addChatMessage(`You cut some ${spec[1].replace('Timber: ', '')} timber.`, 'good'); if (Math.random() < 0.4) { obj.depleted = true; obj.respawnTimer = obj.scenery ? 30 : 10; player.task = null; if (obj.scenery) { setSceneryTreeFelled(obj, true); sceneryFelled.add(obj); } } }
      else player.task = null;
    }
    return;
  }
  if (t.endsWith('_rock')) {
    const table = { essence_rock: [1, 'Raw Aether Crystal', 28, '#22d3ee'], copper_rock: [1, 'Sun-Copper Ore', 34, '#f97316'], tin_rock: [1, 'Ash-Tin Ore', 34, '#cbd5e1'], iron_rock: [5, 'Cobalt Ore', 60, '#60a5fa'], mithril_rock: [12, 'Aetherium Ore', 105, '#818cf8'], adamant_rock: [16, 'Void-Glass Ore', 155, '#34d399'] };
    const spec = table[t];
    if (lvl('Geo-Mining') < spec[0]) { addChatMessage(`You need Geo-Mining ${spec[0]} to mine the ${obj.name}.`, 'warn'); player.task = null; return; }
    player.gatherCd = 1;
    animatePlayer('mine', 0.5); playSound('mine');
    burst(obj.x, top + 0.6, obj.y, spec[3], 8, { speed: 2, up: 2, size: 0.15 });
    if (Math.random() < 0.45 + lvl('Geo-Mining') * 0.01) {
      if (addItem(spec[1])) { gainXp('Geo-Mining', spec[2]); addChatMessage(`You mine some ${spec[1]}.`, 'loot'); if (t !== 'essence_rock') { obj.depleted = true; obj.respawnTimer = 9; player.task = null; } }
      else player.task = null;
    }
    return;
  }
  if (t === 'furnace') {
    let made = null;
    if (countItem('Void-Glass Ore') && lvl('Artifice') >= 18) { removeItems('Void-Glass Ore', 1); made = ['Void-Glass Alloy', 120]; }
    else if (countItem('Aetherium Ore') && lvl('Artifice') >= 12) { removeItems('Aetherium Ore', 1); made = ['Aetherium Alloy', 85]; }
    else if (countItem('Cobalt Ore') && lvl('Artifice') >= 5) { removeItems('Cobalt Ore', 1); made = ['Cobalt Alloy', 50]; }
    else if (countItem('Sun-Copper Ore') && countItem('Ash-Tin Ore')) { removeItems('Sun-Copper Ore', 1); removeItems('Ash-Tin Ore', 1); made = ['Sun-Brass Alloy', 35]; }
    if (!made) { addChatMessage('You need Sun-Copper and Ash-Tin, Cobalt (Artifice 5), Aetherium (12) or Void-Glass (18) ore.', 'warn'); player.task = null; return; }
    addItem(made[0]); gainXp('Artifice', made[1]); playSound('mine');
    animatePlayer('melee', 0.5);
    burst(obj.x, top + 0.5, obj.y + 0.5, 0xfb923c, 14, { speed: 2, up: 2 });
    addChatMessage(`You smelt a ${made[0]}.`, 'loot');
    player.gatherCd = 2;
    return;
  }
  if (t.startsWith('fishing_')) {
    const table = { fishing_shrimp: [1, 'Raw Mire Prawn', 30], fishing_trout: [5, 'Raw Prism Trout', 60], fishing_lobster: [10, 'Raw Solaris Lobster', 95], fishing_shark: [15, 'Raw Leviathan Fin', 150] };
    const spec = table[t];
    if (lvl('Tide-Harvest') < spec[0]) { addChatMessage(`You need Tide-Harvest ${spec[0]} to fish here.`, 'warn'); player.task = null; return; }
    player.gatherCd = 2;
    animatePlayer('cast', 0.6);
    burst(obj.x + 0.6, top, obj.y, 0xa5f3fc, 6, { speed: 1, up: 1.5, size: 0.15 });
    if (Math.random() < 0.4 + lvl('Tide-Harvest') * 0.01) {
      if (addItem(spec[1])) { gainXp('Tide-Harvest', spec[2]); addChatMessage(`You catch a ${spec[1].replace('Raw ', '')}.`, 'accent'); playSound('pickup'); }
      else player.task = null;
    }
    return;
  }
  if (t === 'campfire') {
    const idx = player.inventory.findIndex(k => ITEMS[k]?.type === 'raw_food');
    if (idx === -1) { addChatMessage('You have nothing raw to cook.', 'muted'); player.task = null; return; }
    const raw = player.inventory[idx], it = ITEMS[raw];
    if (lvl('Gastronomy') < it.reqCook) { addChatMessage(`You need Gastronomy ${it.reqCook} to cook ${raw}.`, 'warn'); player.task = null; return; }
    player.inventory.splice(idx, 1);
    animatePlayer('cast', 0.5);
    const burn = Math.max(0.05, 0.3 - lvl('Gastronomy') * 0.02);
    if (Math.random() < burn) {
      addItem('Carbonized Slag'); addChatMessage(`You burn the ${raw.replace('Raw ', '')}.`, 'muted');
      if (currentStep()?.id === 'p8' && !player.inventory.some(k => ITEMS[k]?.type === 'raw_food')) addChatMessage('Burnt it. Instructor Hale keeps spare prawns and timber: ask him for another.', 'quest');
    }
    else { addItem(it.cooked); campaignEvent('cook'); gainXp('Gastronomy', it.xp); addChatMessage(`You cook ${it.cooked}.`, 'good'); burst(obj.x, top + 0.6, obj.y, 0xfb923c, 8, { speed: 1, up: 2 }); }
    player.gatherCd = 2;
    markDirty('inv');
  }
}

function assignNewSlayerTask() {
  const lvlOf = (name) => (npcs.find(n => n.name === name) || { level: 99 }).level;
  const cl = getCombatLevel();
  let pool = SLAYER_POOL.filter(h => lvlOf(h.target) <= cl + 4);
  if (!pool.length) pool = SLAYER_POOL.slice(0, 2);
  const choice = pool[Math.floor(Math.random() * pool.length)];
  const q = GAME_DATA.quests.filter(q => q.kind === 'hunt')[SLAYER_POOL.indexOf(choice)];
  if (!startQuest(q.id)) return;
  addChatMessage(`Arbiter Kaelen: "Eliminate ${choice.count} ${choice.target}${choice.count > 1 ? 's' : ''}."`, 'npc');
  showToast('New hunt', `${choice.count}x ${choice.target}`, 'quest');
  markDirty('journal');
}

/* ---------- Using items ---------- */
function useInventoryItem(index) {
  const key = player.inventory[index];
  const it = ITEMS[key];
  if (!it) return;
  if (activeModal === 'bank') { player.inventory.splice(index, 1); depositItemToBank(key); renderBankModal(); markDirty('inv'); playSound('click'); return; }
  if (activeModal === 'shop') {
    const val = Math.max(1, Math.floor((it.value || 10) * 0.65));
    player.inventory.splice(index, 1); player.coins += val;
    addChatMessage(`Sold ${key} for ${val} Credits.`, 'loot'); playSound('pickup'); markDirty('inv'); markDirty('bars'); return;
  }
  const top = tileTop(player.x, player.y);
  if (it.type === 'food' || it.type === 'medkit') {
    player.inventory.splice(index, 1);
    const heal = Math.min(Math.round((it.heal || 4) * (hasSpec('Field Medic') ? 1.6 : 1)), player.maxHp - player.hp);
    player.hp += heal;
    playSound('heal');
    addSplat(player.visX, top + 2, player.visY, `+${heal}`, 'heal');
    addChatMessage(it.type === 'medkit' ? `You apply the ${key}. +${heal} HP.` : `You eat the ${key}. +${heal} HP.`, 'good');
    player.attackCd = Math.max(player.attackCd, 2);
  } else if (it.type === 'potion') {
    player.inventory.splice(index, 1);
    playSound('magic');
    if (it.effect === 'str') { player.tempStr = it.boost; player.tempStrTicks = 60; addChatMessage(`${key}: +${it.boost} impact.`, 'accent'); }
    else if (it.effect === 'energy') { player.energy = Math.min(100, player.energy + it.boost); markDirty('bars'); addChatMessage(`${key}: Overdrive charged to ${player.energy}%.`, 'accent'); }
    else if (it.effect === 'super') { player.tempStr = it.boost; player.tempStrTicks = 60; player.hp = Math.min(player.maxHp, player.hp + 9); addChatMessage(`${key}: +${it.boost} impact and +9 HP.`, 'accent'); }
    burst(player.visX, top + 1, player.visY, it.color, 14, { speed: 1.2, up: 2 });
  } else if (it.type === 'herb') {
    if (lvl('Bio-Synthesis') < it.reqHerb) { addChatMessage(`You need Bio-Synthesis ${it.reqHerb} to synthesise ${key}.`, 'warn'); return; }
    player.inventory.splice(index, 1);
    addItem(it.potion);
    playSound('magic'); gainXp('Bio-Synthesis', it.xp);
    addChatMessage(`You synthesise a ${it.potion}.`, 'good');
  } else if (it.type === 'cache') {
    player.inventory.splice(index, 1);
    const coins = 120 + Math.floor(Math.random() * 380);
    player.coins += coins;
    const lvlBand = Math.max(getCombatLevel(), 1);
    const got = rollLootTable(CACHE_TABLE, lvlBand);
    const bits = [`${coins} Credits`];
    if (got) { let added = 0; for (let i = 0; i < got.n; i++) { if (addItem(got.key, true)) added++; else dropGround(got.key, player.x, player.y, true); } bits.push(got.n > 1 ? `${got.n} × ${got.key}` : got.key); if (added < got.n) addChatMessage('Your pack is full, so some of it drops at your feet.', 'warn'); }
    playSound('pickup');
    burst(player.visX, top + 1, player.visY, 0xf5c56b, 24, { speed: 2, up: 3 });
    addChatMessage(`You crack open the Starfall Cache: ${bits.join(' and ')}.`, 'rare');
    showToast('Starfall Cache', bits.join(' · '), 'quest');
    markDirty('bars');
  } else if (it.type === 'logs') {
    if (objectBlock.has(tKey(player.x, player.y)) || [6, 9, 10, 11, 12].includes(map[player.y][player.x])) { addChatMessage('You cannot light a beacon here.', 'warn'); return; }
    player.inventory.splice(index, 1);
    playSound('chop');
    gainXp('Pyro-Core', it.fmXp || 35);
    const fire = { id: 10000 + Math.floor(Math.random() * 1e6), type: 'campfire', name: 'Pyro-Beacon', action: 'Cook', x: player.x, y: player.y, depleted: false, respawnTimer: 0, tempCampfire: true, desc: 'A field beacon. Cook your catch on it.' };
    worldObjects.push(fire);
    const m = create3DWorldObjectMesh(fire); scene.add(m); objectMeshes.set(fire.id, m);
    fire.expire = 40; fire.depleted = false;
    setTimeout(() => { fire.depleted = true; fire.respawnTimer = 1; }, 40 * TICK_MS);
    rebuildObjectBlock();
    // step off the beacon
    const off = DIRS8.map(([dx, dy]) => ({ x: player.x + dx, y: player.y + dy })).find(p => isTileWalkable(p.x, p.y));
    if (off) player.path = [off];
    addChatMessage(`You kindle a Pyro-Beacon. +${it.fmXp} Pyro-Core XP.`, 'loot');
  } else if (EQUIP_SLOTS.includes(it.type)) {
    if (it.req && lvl(it.req[0]) < it.req[1]) { addChatMessage(`You need ${it.req[0]} ${it.req[1]} to use the ${key}.`, 'warn'); playSound('deny'); return; }
    const slot = it.type;
    const prev = player.equipment[slot];
    player.inventory.splice(index, 1);
    if (prev) player.inventory.push(prev);
    player.equipment[slot] = key;
    if (slot === 'sidearm' || slot === 'primary') player.visualSlot = slot;
    syncPlayerEquipmentVisuals();
    playSound('click');
    addChatMessage(`Equipped ${key}.`, 'accent');
    markDirty('equip');
  } else {
    addChatMessage(`${key}: ${it.desc || 'A useful material.'}`, 'muted');
  }
  markDirty('inv'); markDirty('bars');
}

function unequip(slot) {
  const k = player.equipment[slot];
  if (!k) return;
  if (player.inventory.length >= MAX_INV_SLOTS) { addChatMessage('Your pack is full.', 'warn'); return; }
  player.equipment[slot] = null;
  player.inventory.push(k);
  if (player.visualSlot === slot) player.visualSlot = slot === 'primary' ? 'sidearm' : 'primary';
  syncPlayerEquipmentVisuals();
  markDirty('inv'); markDirty('equip'); markDirty('bars');
}

function eatBestFood() {
  let best = -1, bestHeal = 0;
  const missing = player.maxHp - player.hp;
  player.inventory.forEach((k, i) => {
    const h = (ITEMS[k]?.type === 'food' || ITEMS[k]?.type === 'medkit') ? ITEMS[k].heal : 0;
    if (!h) return;
    const score = h <= missing ? h : missing - (h - missing) * 0.5;
    if (best === -1 || score > bestHeal) { best = i; bestHeal = score; }
  });
  if (best === -1) { addChatMessage('You have no food or medkits.', 'warn'); playSound('deny'); return; }
  const prevModal = activeModal; activeModal = null;
  useInventoryItem(best);
  activeModal = prevModal;
}

function depositItemToBank(key) {
  const ex = player.bank.find(b => b.itemKey === key);
  if (ex) ex.count++; else player.bank.push({ itemKey: key, count: 1 });
}

/* ---------- Campaign ---------- */
function campaignOnTalk(npc) {
  const step = currentStep();
  if (!step || step.type !== 'talk' || step.npc !== npc.id) return false;
  showDialogue(step.dialogue, () => { recordQuestEvent('talk', npc); completeCampaignStep(); });
  return true;
}
function campaignEvent(name) {
  const step = currentStep();
  recordQuestEvent('event', name);
  if (step && questReady(MAIN_QUEST)) completeCampaignStep();
}
function campaignOnKill(npc) {
  const step = currentStep();
  if (!step || !questMatches(questStep(MAIN_QUEST), 'kill', npc)) return;
  markDirty('journal');
  if (campaignState().progress >= step.count) completeCampaignStep();
  else showToast(step.title, `${campaignState().progress}/${step.count} ${step.target}`, 'quest');
}
function campaignOnInteract(obj) {
  const step = currentStep();
  if (!step || step.type !== 'interact' || step.obj !== obj.id) return false;
  recordQuestEvent('interact', obj);
  const top = tileTop(obj.x, obj.y);
  burst(obj.x, top + 1, obj.y, obj.color || 0x67e8f9, 60, { speed: 3, up: 4, life: 1.4, grav: -1 });
  spawnShockwave(obj.x, top + 0.05, obj.y, obj.color || 0x67e8f9, 5, 0.9);
  playSound('discover');
  completeCampaignStep();
  return true;
}

function grantReward(r) {
  if (!r) return [];
  const bits = [];
  if (r.coins) { player.coins += r.coins; bits.push(`${r.coins} Credits`); }
  if (r.cells) { player.cells += r.cells; bits.push(`${r.cells} cells`); }
  if (r.slugs) { player.slugs += r.slugs; bits.push(`${r.slugs} slugs`); }
  if (r.items) for (const k of r.items) {
    const it = ITEMS[k];
    if (r.equip && it && EQUIP_SLOTS.includes(it.type)) { const prev = player.equipment[it.type]; if (prev) addItem(prev, true); player.equipment[it.type] = k; player.visualSlot = it.type === 'sidearm' ? 'sidearm' : 'primary'; syncPlayerEquipmentVisuals(); bits.push(`${k} (equipped)`); continue; }
    if (!addItem(k, true)) { depositItemToBank(k); bits.push(`${k} (sent to vault)`); } else bits.push(k);
  }
  if (r.xp) { gainXp(r.xp[0], r.xp[1]); bits.push(`${r.xp[1]} ${r.xp[0]} XP`); }
  return bits;
}

function completeCampaignStep() {
  const step = currentStep();
  if (!step) return;
  advanceQuest(MAIN_QUEST, { present: (bits, commit) => {
    playSound('quest');
    addChatMessage(`Campaign: "${step.title}" complete.${bits.length ? ' Reward: ' + bits.join(', ') + '.' : ''}`, 'quest');
    showToast(step.title, bits.length ? bits.join(' · ') : 'Objective complete', 'quest');
    const advance = () => {
      commit();
      const prevAct = step.act;
      if (campaignState().status === 'done') {
        showActBanner('Campaign complete', 'The Continuum holds. Vaelor is yours to explore.');
      } else {
        const next = CAMPAIGN[campaignState().step];
        if (next.act !== prevAct) showActBanner(CAMPAIGN_TITLE.full, `${actName(next.act)}: ${CAMPAIGN_ACTS[next.act].title}`);
        addChatMessage(`New objective: ${next.objective}.`, 'quest');
      }
      rebuildObjectBlock();
      markDirty('journal'); markDirty('inv'); markDirty('bars');
      saveGame(false);
    };
    if (step.complete && step.complete.length) showDialogue(step.complete, advance);
    else advance();
  } });
}

function campaignTargetPos() {
  const step = currentStep();
  if (!step || step.anywhere) return null;
  if (step.type === 'talk') { const n = npcById(step.npc); if (n && !n.dead) return { x: n.visX ?? n.x, y: n.visY ?? n.y, tx: n.x, ty: n.y }; }
  return { x: step.loc[0], y: step.loc[1], tx: step.loc[0], ty: step.loc[1] };
}

/* ---------- Player tile change, regions ---------- */
function onPlayerTileChanged() {
  const b = getBiome(player.x, player.y);
  if (b !== currentBiome) {
    currentBiome = b;
    if (!player.discovered.includes(b)) {
      player.discovered.push(b);
      if (gameStarted) {
        showRegionCard(BIOMES[b].name, BIOMES[b].sub);
        playSound('discover');
        gainXp('Parkour', 60);
        markDirty('journal');
      }
    }
  }
  updateRegionLabel();
}

/* ---------- Floating text ---------- */
function addSplat(x, y, z, text, kind) { if (text === '') return; splats.push({ x, y, z, text, kind, age: 0, dx: (Math.random() - 0.5) * 0.4 }); }
function addOverheadBark(entity, text, color = '#a5f3fc') {
  const ex = overheadBarks.find(b => b.entity === entity);
  if (ex) { ex.text = text; ex.ttl = 6; ex.color = color; }
  else overheadBarks.push({ entity, text, ttl: 6, color });
}

/* ---------- Save / load ---------- */
const SAVE_KEY = 'vaelor_starfall_save_v8';
const OLD_SAVE_KEYS = ['vaelor_starfall_save_v7', 'vaelor_starfall_save_v6', 'vaelor_starfall_save_v5', 'vaelor_starfall_save_v4', 'vaelor_starfall_save_v3'];
function saveGame(manual) {
  if (!gameStarted) return false;
  try {
    const p = player;
    const data = {
      v: 8, name: p.name, specs: p.specs, runEnergy: p.runEnergy, x: p.x, y: p.y, hp: p.hp, maxHp: p.maxHp, coins: p.coins, cells: p.cells, slugs: p.slugs,
      equipment: p.equipment, inventory: p.inventory, bank: p.bank, skills: p.skills, world: p.world,
      discovered: p.discovered, lore: p.lore, runEnabled: p.runEnabled, autoRetaliate: p.autoRetaliate, doctrine: p.doctrine,
      weaponMode: p.weaponMode, energy: p.energy, kills: p.kills, waypoint: p.waypoint,
      settings: { droneIndex, quality: GFX.quality, sfx: sfxEnabled, labels: showWorldLabels, roofMode }
    };
    localStorage.setItem(SAVE_KEY, JSON.stringify(data));
    if (manual) { addChatMessage('Progress saved on this device.', 'good'); flashSaveStatus(); }
    return true;
  } catch (e) {
    if (manual) addChatMessage('Could not save: this browser is blocking storage.', 'warn');
    return false;
  }
}
/* Saves are versioned. Each migration upgrades one version, so old saves always load. */
const SAVE_MIGRATIONS = {
  3: (d) => {
    // v3 used a square-root level curve; keep each skill's level on the new RuneScape curve
    const oldLevel = (k, xp) => k === 'Vitality' ? Math.max(10, Math.floor(10 + Math.sqrt(xp / 20))) : Math.floor(1 + Math.sqrt(xp / 25));
    for (const [k, s] of Object.entries(d.skills || {})) { const l = Math.min(99, oldLevel(k, s.xp || 0)); s.xp = XP_TABLE[l]; s.level = l; }
    const xp = k => d.skills?.[k]?.xp || 0;
    const scores = { Blade: xp('Vanguard') + xp('Kinetic'), Gunner: xp('Marksman'), Artificer: xp('Arcanistry') };
    d.cls = Object.entries(scores).sort((a, b) => b[1] - a[1])[0][0];
    d.runEnergy = 100;
    d.v = 4;
    return d;
  },
  4: (d) => {
    // v5 adds the Starborn Induction (9 prologue steps) before the campaign; players already past it skip it
    d.campaign = d.campaign || { step: 0, progress: 0, done: false };
    if (!d.campaign.done) d.campaign.step = (d.campaign.step || 0) + CAMPAIGN.filter(s => s.act === 'P').length;
    d.specs = { Blade: null, Gunner: null, Artificer: null };
    delete d.cls;
    d.v = 5;
    return d;
  },
  5: (d) => {
    // v6 moves to the 1,024 x 800 world: each area moved as a block, so move the player with theirs
    if (typeof d.x === 'number' && typeof d.y === 'number') {
      const [x, y] = relocate(d.x, d.y);
      [d.x, d.y] = snapTile(x, y, (a, b) => openTile(a, b), 12);
    }
    d.waypoint = null;
    d.v = 6;
    return d;
  },
  6: (d) => {
    // v7 cuts Resonance, Aspects, the Aegis Barrier and Echo Matrices (story reset, 16 November 2026)
    if (d.skills) delete d.skills.Resonance;
    delete d.prayer; delete d.maxPrayer; delete d.prayers;
    const swap = { 'Echo Matrix': 'Salvaged Servo', 'Resonance Serum': 'Overdrive Tonic' };
    if (Array.isArray(d.inventory)) d.inventory = d.inventory.map(k => swap[k] || k);
    if (Array.isArray(d.bank)) {
      const merged = new Map();
      for (const b of d.bank) { const k = swap[b.itemKey] || b.itemKey; merged.set(k, (merged.get(k) || 0) + (b.count || 0)); }
      d.bank = [...merged].map(([itemKey, count]) => ({ itemKey, count }));
    }
    d.v = 7;
    return d;
  },
  7: (d) => {
    d.world = worldFromLegacy(d);
    for (const k of ['campaign', 'flags', 'killCounts', 'slayerTask', 'completedQuests']) delete d[k];
    d.v = 8;
    return d;
  }
};
function migrateSave(d) {
  if (!validVaelorSave(d)) return null;
  while (d && d.v < 8 && SAVE_MIGRATIONS[d.v]) d = SAVE_MIGRATIONS[d.v](d);
  return d && d.v === 8 && validVaelorSave(d) ? d : null;
}
function readSave() {
  try {
    const raw = localStorage.getItem(SAVE_KEY);
    if (raw) return migrateSave(JSON.parse(raw));
    for (const k of OLD_SAVE_KEYS) { const old = localStorage.getItem(k); if (old) return migrateSave(JSON.parse(old)); }
    return null;
  } catch (e) { return null; }
}
function exportSave() { saveGame(false); try { return btoa(unescape(encodeURIComponent(localStorage.getItem(SAVE_KEY) || ''))); } catch (e) { return ''; } }
function importSave(str) { try { if (typeof str !== 'string' || str.length > 2000000) return false; const d = migrateSave(JSON.parse(decodeURIComponent(escape(atob(str.trim()))))); if (!d) return false; localStorage.setItem(SAVE_KEY, JSON.stringify(d)); return true; } catch (e) { return false; } }
function applySave(d) {
  d = migrateSave(d);
  if (!d) return false;
  const p = defaultPlayer();
  if (d.specs) p.specs = Object.assign(p.specs, d.specs);
  const fields = ['name', 'x', 'y', 'hp', 'maxHp', 'coins', 'cells', 'slugs', 'discovered', 'lore', 'runEnabled', 'autoRetaliate', 'doctrine', 'weaponMode', 'energy', 'kills', 'waypoint', 'runEnergy'];
  for (const f of fields) if (d[f] !== undefined) p[f] = d[f];
  if (d.world) p.world = JSON.parse(JSON.stringify(d.world));
  if (Array.isArray(d.inventory)) p.inventory = d.inventory.filter(k => ITEMS[k]).slice(0, MAX_INV_SLOTS);
  if (Array.isArray(d.bank)) p.bank = d.bank.filter(b => ITEMS[b.itemKey] && b.count > 0);
  if (d.equipment) for (const s of EQUIP_SLOTS) p.equipment[s] = (d.equipment[s] && ITEMS[d.equipment[s]]?.type === s) ? d.equipment[s] : (d.equipment[s] === null ? null : p.equipment[s]);
  if (d.skills) for (const k of SKILL_ORDER) if (d.skills[k]) p.skills[k] = { xp: d.skills[k].xp || 0, level: levelFor(k, d.skills[k].xp || 0) };
  p.maxHp = p.skills.Vitality.level;
  p.hp = clamp(p.hp, 1, p.maxHp);
  if (!isTileWalkable(p.x, p.y)) { p.x = START_POS.x; p.y = START_POS.y; }
  p.visX = p.x; p.visY = p.y;
  player = p;
  for (const n of npcs) if (npcPermanentlyDead(n)) n.dead = true;
  const s = d.settings || {};
  if (typeof s.droneIndex === 'number') droneIndex = s.droneIndex % DRONE_TYPES.length;
  if (s.quality) GFX.quality = s.quality;
  if (typeof s.sfx === 'boolean') sfxEnabled = s.sfx;
  if (typeof s.labels === 'boolean') showWorldLabels = s.labels;
  if (s.roofMode) roofMode = s.roofMode;
}
function wipeSave() { try { localStorage.removeItem(SAVE_KEY); for (const k of OLD_SAVE_KEYS) localStorage.removeItem(k); } catch (e) {} }

player = defaultPlayer();
initGroundItems();

;
/* Conversations: branching dialogue trees, rumours, directions and errands for non-hostile NPCs.
   The words live in data/: lines.json (greetings, rumours, place and role lines), errands.json and dialogue.json (the trees).
   This file runs them: errand logic, the helpers that build sentences from the live world, and the tree interpreter. */

let convo = null; // { npc, tree, node, visit }

/* ---------- Shared lines (data/lines.json) ---------- */
const PLACE_LINES = GAME_DATA.lines.places;     // region: lines for "What is this place?"
const RUMOURS = GAME_DATA.lines.rumours;        // campaign step id (or done): lines for "Heard any news?"
const GREETINGS = GAME_DATA.lines.greetings;    // role: opening lines
const ROLE_TALK = GAME_DATA.lines.roleTalk;     // role: one extra question and its answers

/* ---------- Errands ---------- */
function questOptions(id) {
  const q = SIDE_QUESTS[id], st = questState(id);
  if (st === 'done' || st === 'locked' || (!st && !canStartQuest(id))) return [];
  if (!st) return [{ label: 'Do you need help with anything?', next: `q:${id}:offer` }];
  const prog = questProgress(id);
  if (prog >= q.count) return [{ label: q.type === 'fetch' ? `Here: ${q.count} ${q.item}.` : `The ${q.target}s are dealt with.`, cls: 'gold', action: () => finishQuest(id) }];
  return [{ label: `About "${q.title}"...`, next: `q:${id}:remind` }];
}
function finishQuest(id) {
  const q = SIDE_QUESTS[id];
  const bits = completeQuest(id);
  if (!bits) return questState(id) === 'done' ? `q:${id}:done` : 'root';
  playSound('quest');
  showToast(q.title, bits.join(' · '), 'quest');
  addChatMessage(`Errand "${q.title}" complete. ${bits.join(', ')}.`, 'quest');
  markDirty('journal'); markDirty('inv'); markDirty('bars');
  return `q:${id}:done`;
}
function questNode(id, part) {
  const q = SIDE_QUESTS[id];
  if (part === 'offer') return { text: q.offer + (q.type === 'fetch' ? ` (Bring ${q.count} ${q.item}.)` : ` (Defeat ${q.count} ${q.target}s.)`), options: [
    { label: 'I will do it.', cls: 'gold', action: () => { if (!startQuest(id)) return 'root'; showToast('Errand accepted', q.title, 'quest'); addChatMessage(`Errand accepted: ${q.title}.`, 'quest'); markDirty('journal'); return `q:${id}:accepted`; } },
    { label: 'Not right now.', next: 'root' }] };
  if (part === 'accepted') return { text: q.accept, options: [{ label: 'Back.', next: 'root' }, { label: 'Goodbye.', next: 'end' }] };
  if (part === 'remind') return { text: `${q.accept} (${questProgress(id)} of ${q.count} so far.)`, options: [{ label: 'Back.', next: 'root' }, { label: 'Goodbye.', next: 'end' }] };
  if (part === 'done') return { text: q.done, options: [{ label: 'Glad to help.', next: 'root' }, { label: 'Goodbye.', next: 'end' }] };
  return null;
}

/* ---------- Helpers ---------- */
function pickLine(arr, npc, salt = 0) { return arr[Math.abs(npc.id * 7 + salt + (convo ? convo.visit : 0)) % arr.length]; }
const DIR_WORDS = ['north', 'north-east', 'east', 'south-east', 'south', 'south-west', 'west', 'north-west'];
function directionWord(dx, dy) { return DIR_WORDS[(Math.round(Math.atan2(dx, -dy) / (Math.PI / 4)) + 8) % 8]; }
function describeRoute(fromX, fromY, toX, toY) {
  const d = cheb(fromX, fromY, toX, toY);
  if (d <= 3) return 'right here';
  return `about ${d} sectors ${directionWord(toX - fromX, toY - fromY)} of here`;
}
function setWaypoint(x, y, label) {
  player.waypoint = { x, y, label };
  addChatMessage(`Waypoint set: ${label}. Follow the cyan beacon.`, 'accent');
}
function directTo(npc, kind, label) {
  let best = null, bd = 1e9;
  if (kind === 'lodge') best = npcById(139);
  else for (const o of worldObjects) { if (o.type !== kind || isObjHidden(o)) continue; const d = cheb(npc.x, npc.y, o.x, o.y); if (d < bd) { bd = d; best = o; } }
  if (!best) return 'I could not tell you, sorry.';
  setWaypoint(best.x, best.y, best.name || label);
  return `The nearest ${label} is ${describeRoute(npc.x, npc.y, best.x, best.y)}. I have marked it for you.`;
}
function threatReport(npc) {
  let best = null, bd = 1e9;
  for (const n of npcs) { if (n.dead || n.neutral) continue; const d = cheb(npc.x, npc.y, n.x, n.y); if (d < bd) { bd = d; best = n; } }
  if (!best || bd > 45) return 'All quiet around here. Long may it last.';
  return `Watch yourself. There are ${best.name}s ${describeRoute(npc.x, npc.y, best.x, best.y)}. Tier ${best.level}. ${best.style !== 'melee' ? 'They attack from range.' : 'They hit hard up close.'}`;
}
function rumourFor(npc, salt) {
  const step = currentStep();
  const pool = step ? RUMOURS[step.id] : RUMOURS.done;
  return pickLine(pool || RUMOURS.done, npc, salt);
}
const BYE = { label: 'Goodbye.', next: 'end' };
const BACK = { label: 'Back.', next: 'root' };

/* ---------- Trees (data/dialogue.json) ----------
   The data describes each tree; compileTree turns it into the shape the conversation runner below uses
   (nodes with text and options; an option has a label and either a next node or an action).
   Three small tables say what the data may refer to:
     DIALOGUE_CONDITIONS  what "when" can test
     DIALOGUE_VALUES      what {placeholders} in text can show
     DIALOGUE_ACTIONS     named actions for "run": things that need live game state, so they stay as code
   tools/validate-data.js checks every name used in the data against these tables. */
const DIALOGUE = GAME_DATA.dialogue;
const roleOf = npc => npc.role || 'citizen';
const specsOf = cls => Object.entries(SPECS).filter(([, s]) => s.cls === cls);

const DIALOGUE_CONDITIONS = {
  // story and pack
  step: v => currentStep()?.id === v,                                   // the current campaign step is this one
  hasStep: v => !!currentStep() === v,                                  // the campaign still has a step to do
  campaignDone: v => !!(campaignState().status === 'done') === v,
  underStrength: v => { const s = currentStep(); return (!!s && s.suggest > getCombatLevel()) === v; },
  hasItem: v => player.inventory.includes(v),
  lacksItem: v => !player.inventory.includes(v),
  hasItemType: v => player.inventory.some(k => ITEMS[k]?.type === v),
  lacksItemType: v => !player.inventory.some(k => ITEMS[k]?.type === v),
  flag: v => !!player.world.flags[v],
  notFlag: v => !player.world.flags[v],
  quest: v => v.state === 'available' ? canStartQuest(v.id) : questState(v.id) === v.state,
  standing: v => (player.world.factions[v.faction] ?? -101) >= standingNumber(v.min),
  notoriety: v => (player.world.notoriety[v.settlement] || 0) <= v.max,
  hasHunt: v => !!currentHunt() === v,
  // who you are talking to
  role: (v, c) => roleOf(c.npc) === v,
  roleIsNot: (v, c) => roleOf(c.npc) !== v,
  hasRoleTalk: (v, c) => !!ROLE_TALK[roleOf(c.npc)] === v,
  npcHas: (v, c) => !!c.npc[v],
  // templates (the instructors): params of the tree, and the class named by its cls param
  param: (v, c) => Object.entries(v).every(([k, x]) => c.params[k] === x),
  hasSpec: (v, c) => !!player.specs[c.params.cls] === v,
  specReady: (v, c) => (lvl(CLASSES[c.params.cls].lead) >= SPEC_LEVEL) === v,
  // what the option's "run" action reported
  result: (v, c) => c.result === v,
  // combining
  any: (v, c) => v.some(w => testWhen(w, c)),
  not: (v, c) => !testWhen(v, c)
};
function testWhen(when, c) { return Object.entries(when).every(([k, v]) => DIALOGUE_CONDITIONS[k](v, c)); }

const DIALOGUE_VALUES = {
  'npc.pickpocketLvl': c => c.npc.pickpocketLvl,
  'roleTalk.label': c => ROLE_TALK[roleOf(c.npc)]?.label,
  'hunt.count': () => currentHunt()?.count,
  'hunt.target': () => currentHunt()?.target,
  'hunt.remaining': () => currentHunt()?.remaining,
  'hunt.coins': () => currentHunt()?.coins,
  'step.objectiveLower': () => currentStep()?.objective.toLowerCase(),
  'class.blurb': c => CLASSES[c.params.cls]?.blurb,
  'class.lead': c => CLASSES[c.params.cls]?.lead,
  'class.leadLevel': c => CLASSES[c.params.cls] && lvl(CLASSES[c.params.cls].lead),
  'class.spec': c => player.specs[c.params.cls],
  'class.specList': c => specsOf(c.params.cls).map(([n, s]) => `${n}: ${s.desc}`).join(' '),
  'spec.level': () => SPEC_LEVEL,
  'spec.name': c => c.spec?.name,
  'spec.desc': c => c.spec?.desc
};
// {name} is looked up in what the action reported, then the tree's params, then DIALOGUE_VALUES. Unknown names are left as written.
function fillText(str, c) {
  return str.replace(/\{([\w.]+)\}/g, (m, key) => {
    const v = c.vars && key in c.vars ? c.vars[key] : key in c.params ? c.params[key] : DIALOGUE_VALUES[key] ? DIALOGUE_VALUES[key](c) : undefined;
    return v === undefined || v === null ? m : String(v);
  });
}

/* Named actions: (npc, args, context) => nothing | 'end' (the conversation was closed) | { text } | { result, vars }.
   An option's "say" is shown after the action; without "say", the action's own text is shown. */
const DIALOGUE_ACTIONS = {
  // lines picked from data/lines.json by who is speaking, where they stand and how far the story has got
  greeting: n => ({ text: pickLine(GREETINGS[roleOf(n)] || GREETINGS.citizen, n) }),
  roleTalk: (n, a) => ({ text: pickLine(ROLE_TALK[roleOf(n)].lines, n, a.salt) }),
  placeLine: (n, a) => ({ text: pickLine(PLACE_LINES[getBiome(n.x, n.y)], n, a.salt) }),
  rumour: (n, a) => ({ text: rumourFor(n, a.salt) }),
  // sentences built from the live world: nearest enemy, nearest station, where the next objective is
  threatReport: n => ({ text: threatReport(n) }),
  directTo: (n, a) => ({ text: directTo(n, a.kind, a.label) }),
  nextObjective: n => { const t = campaignTargetPos(); const step = currentStep(); return { text: t ? `"${step.title}"? That is ${describeRoute(n.x, n.y, t.tx, t.ty)}. Follow the gold beacon.` : `"${step.title}"? You can do that anywhere: ${step.objective.charAt(0).toLowerCase() + step.objective.slice(1)}.` }; },
  // game systems
  pickpocket: n => { closeConversation(); pickpocket(n); return 'end'; },
  assignHunt: () => { assignNewSlayerTask(); },
  locateHunt: n => {
    const t = npcs.filter(x => x.kindId === QUESTS[player.world.activeHunt].steps[0].target && !x.dead).sort((a, b) => cheb(n.x, n.y, a.x, a.y) - cheb(n.x, n.y, b.x, b.y))[0];
    if (!t) return { result: 'none' };
    setWaypoint(t.x, t.y, currentHunt().target);
    return { result: 'found', vars: { 'target.name': t.name, route: describeRoute(n.x, n.y, t.x, t.y) } };
  },
  cancelHunt: () => { cancelQuest(player.world.activeHunt); },
  learnSpec: (n, a, c) => ({ result: learnSpec(c.spec.name) ? 'learned' : 'refused' })
};
// The {placeholders} an action reports for the option's "say" text (so the validator knows they are real)
const DIALOGUE_ACTION_VARS = { locateHunt: ['target.name', 'route'] };
// Panels an option can open with "open" (shops use "shop" with the shop's id)
