  if (droneMesh && droneMesh.visible) {
    const a = t * 1.3;
    droneMesh.position.set(player.visX + Math.cos(a) * 0.9, pTop + 1.7 + Math.sin(t * 2.8) * 0.12, player.visY + Math.sin(a) * 0.9);
    droneMesh.rotation.y = -a;
    const halo = droneMesh.getObjectByName('droneHalo'); if (halo) halo.rotation.z = t * 2.4;
  }
