  // camera follow
  const ease = 1 - Math.exp(-dt * 8);
  camTarget.x += (player.visX - camTarget.x) * ease;
  camTarget.z += (player.visY - camTarget.z) * ease;
  camTarget.y += (pTop + 0.85 - camTarget.y) * ease;
  if (!gameStarted) { camYaw += dt * 0.06; }
  const hd = camDist * Math.cos(camPitch), vd = camDist * Math.sin(camPitch);
  camera.position.set(camTarget.x + Math.sin(camYaw) * hd, camTarget.y + vd, camTarget.z + Math.cos(camYaw) * hd);
  if (shakeAmt > 0.001) { camera.position.x += (Math.random() - 0.5) * shakeAmt; camera.position.y += (Math.random() - 0.5) * shakeAmt; shakeAmt *= Math.pow(0.02, dt); }
  camera.lookAt(camTarget);
